// 產生檔：node tools/build_course_v2.js（來源 tools/content/course_v2/）。不要手改。
window.BUZZ_COURSE_V2_LESSONS = Object.assign(window.BUZZ_COURSE_V2_LESSONS || {}, {"limit-intro":{"id":"limit-intro","prerequisites":["function-intro","piecewise-function"],"next":["limit-one-sided"],"related":["continuity-definition","limit-laws-direct","limit-trig-standard"],"objectives":["用自己的話說出 lim_{x→a} f(x) = L 在問什麼：x 靠近 a 的時候，f(x) 靠近誰。","能從一張數值表估計極限。","分清楚三件不同的事：f(a) 是多少、極限是多少、兩者相不相等。"],"concept":[{"heading":"① 一個代不進去的函數","body":["f(x) = (x² − 1)/(x − 1) 在 x = 1 沒有定義：代進去分母是 0。但 x 靠近 1 的時候，f(x) 好好的有值（見下表）。","從左邊、從右邊靠近，f(x) 都往 2 擠。我們寫成 lim_{x→1} (x² − 1)/(x − 1) = 2。"],"tex":["\\begin{array}{c|ccc|ccc} x & 0.9 & 0.99 & 0.999 & 1.001 & 1.01 & 1.1 \\\\ \\hline f(x) & 1.9 & 1.99 & 1.999 & 2.001 & 2.01 & 2.1 \\end{array}"]},{"heading":"② 極限問的是「靠近」，不是「等於」","body":["lim_{x→a} f(x) = L 的意思是：只要 x 夠靠近 a（但不等於 a），f(x) 就能要多靠近 L 就多靠近 L。","「要多靠近就多靠近」是這個意思：要求 f(x) 跟 L 的差小於 0.1 做得到，小於 0.01 做得到，小於 0.000001 也做得到——只要 x 離 a 夠近。","「不等於 a」是重點：極限完全不看 f 在 a 這一點的值，只看 a 的附近。所以上面的 f 在 x = 1 沒有定義，極限照樣存在。"]},{"heading":"③ 三件不一樣的事","body":["g(x) = x + 1（x ≠ 1），g(1) = 5。","g(1) = 5：函數在那一點的值。lim_{x→1} g(x) = 2：x 靠近 1 時，g(x) = x + 1 靠近 2。兩者不相等。","很多時候兩者剛好相等，那叫做「連續」（〈連續的定義〉）。但不是每次都相等，而微積分最有趣的地方，正好發生在它們不相等、或代不進去的時候。"]},{"heading":"④ 圖形上怎麼看","body":["極限是「沿著曲線從兩邊走向 x = a 時，高度往哪裡去」。曲線在 a 挖洞、或 a 那一點被另外畫在別處，都不影響極限。"]},{"heading":"⑤ 兩個常見誤解","body":["「極限就是把 a 代進去」：只對連續的函數成立。上面的 f 代不進去，g 代進去會得到錯的 5。","「極限是永遠到不了的值」：不一定。lim_{x→3} (2x + 1) = 7，f(3) 也剛好是 7。極限不管到不到得了。"]}],"workedExamples":[{"title":"用數值表估極限","prompt":"估計 lim_{x→1} (x² + x − 2)/(x − 1)","steps":["x = 1 代不進去（分子分母都是 0），所以從兩邊靠近。","x = 0.9、0.99、0.999 時，值是 2.9、2.99、2.999；x = 1.001、1.01、1.1 時，值是 3.001、3.01、3.1。","左右都往 3 擠，估計極限是 3。"],"answer":"3","note":"表格只能「估計」，不能「證明」。從〈直接代入與極限定律〉開始會學怎麼用代數算出來；同一個表格方法之後也會拿來猜 (sin x)/x 的極限（〈三角標準極限〉）。"},{"title":"從圖形讀極限（挖洞＋另外定義）","prompt":"f 的圖形是通過 (0, 1) 與 (3, 4) 的直線，但在 x = 2 挖空，另外定義 f(2) = 1。求 lim_{x→2} f(x) 與 f(2)。","problemId":"gx-022","steps":["直線通過 (0, 1)、(3, 4)，斜率 (4 − 1)/(3 − 0) = 1，所以除了 x = 2 以外 f(x) = x + 1。","x 靠近 2 時，沿著直線走，高度靠近 3。極限是 3。","f(2) 題目另外定義成 1。"],"answer":"lim_{x→2} f(x) = 3，f(2) = 1，兩者不相等"},{"title":"極限剛好等於函數值","prompt":"lim_{x→3} (2x + 1)","problemId":"cx-lim-001","steps":["x 靠近 3 時，2x 靠近 6，2x + 1 靠近 7。","代進去也是 7。多項式沒有洞、沒有跳，極限就等於函數值（〈直接代入與極限定律〉）。"],"answer":"7"}],"pitfalls":["看到 f(a) 沒有定義，就說極限不存在。","把 f(a) 當成極限。","表格只算一邊（左右可能去不同地方，見〈左極限與右極限〉）。"],"checks":[{"ask":"g(x) = x + 1（x ≠ 1），g(1) = 5。lim_{x→1} g(x) 是？","options":[{"label":"5","why":"那是 g(1)。極限不看 x = 1 這一點本身，只看它旁邊。"},{"label":"2","correct":true},{"label":"不存在","why":"x 靠近 1 時 g(x) 穩穩地靠近 2，極限存在。"}]},{"ask":"函數在 x = a 沒有定義，那 lim_{x→a} f(x)：","options":[{"label":"一定不存在","why":"(x² − 1)/(x − 1) 在 1 沒定義，極限卻是 2。"},{"label":"一定是 0","why":"沒有定義不代表是 0，0/0 不是一個數。"},{"label":"可能存在，也可能不存在，要看 a 附近的行為","correct":true}]},{"ask":"h(x) 在 x = 3.9、3.99、3.999 的值是 7.8、7.98、7.998；在 x = 4.001、4.01、4.1 的值是 8.002、8.02、8.2。最合理的估計是？","options":[{"label":"lim_{x→4} h(x) = 8","correct":true},{"label":"lim_{x→4} h(x) = 4","why":"4 是 x 靠近的地方，題目問的是 h(x) 靠近哪裡。"},{"label":"無法判斷，因為表裡沒有 x = 4","why":"極限本來就不看 x = 4 那一點。"}]},{"ask":"「f(x) 能要多靠近 L 就多靠近 L」最接近哪個意思？","options":[{"label":"f(x) 最後會等於 L","why":"不一定等於，只要能任意靠近。"},{"label":"不管要求誤差多小（0.1、0.01、0.000001），只要 x 離 a 夠近都做得到","correct":true},{"label":"f(x) 會越來越接近 L，但永遠差 0.1 以上","why":"那就不是「要多靠近就多靠近」了。"}]}],"practice":[{"id":"fd-lim-001","core":true},{"id":"fd-lim-002","core":true},{"id":"lx-tab-001","core":true},{"id":"lx-tab-002","note":"表格裡只有右邊的值；題目暗示左右一樣（函數是偶函數），之後〈左極限與右極限〉會說為什麼兩邊都要看。"}]},"limit-one-sided":{"id":"limit-one-sided","prerequisites":["limit-intro","piecewise-function"],"next":["limit-existence"],"related":["infinite-limits"],"objectives":["看懂 x → a⁻ 與 x → a⁺：只從一邊靠近 a。","會算分段函數、絕對值、取整函數在分界點的左右極限。","知道函數只在一側有定義時，只能談那一側的極限。"],"concept":[{"heading":"① 只從一邊靠近","body":["lim_{x→a⁻} f(x) = L：x 從 a 的左邊（x < a）靠近 a 時，f(x) 靠近 L，叫左極限。lim_{x→a⁺} 是從右邊（x > a），叫右極限。","上標的 − 與 + 表示方向，不是負號：x → 3⁻ 是「比 3 小一點點的地方」，跟 −3 無關。"]},{"heading":"② 為什麼需要它：兩邊可能去不同地方","body":["f(x) = x（x < 2），x + 2（x ≥ 2）。x 從左邊靠近 2 時用第一段，高度靠近 2；從右邊靠近時用第二段，高度靠近 4。","一個「兩邊一起看」的極限沒辦法描述這件事，拆成左、右各自說就清楚了：左極限 2，右極限 4。f(2) = 4 是第三件事，跟左極限無關。"]},{"heading":"③ 算法：在那一側用那一側的式子","body":["左極限只看 x < a 的部分，所以分段函數要用 x < a 那一段；絕對值要先依正負拆開。例：x > 0 時 |x|/x = x/x = 1，x < 0 時 |x|/x = −x/x = −1，所以 0 的右極限是 1、左極限是 −1。","取整函數 ⌊x⌋ 是「不超過 x 的最大整數」：⌊1.7⌋ = 1，⌊2⌋ = 2，⌊−0.5⌋ = −1。x 在 [1, 2) 裡 ⌊x⌋ = 1，所以 lim_{x→2⁻} ⌊x⌋ = 1，而 lim_{x→2⁺} ⌊x⌋ = 2。"]},{"heading":"④ 只有一側有定義","body":["√x 在 x < 0 沒有定義，在 0 只能談右極限：lim_{x→0⁺} √x = 0。√(x − 3) 在 3 也一樣。","單側極限也可以「跑到無窮」：x → 0⁺ 時 1/x 越來越大，x → 0⁻ 時越來越負。這種情況在〈無窮極限與垂直漸近線〉處理。"]}],"workedExamples":[{"title":"絕對值除以自己","prompt":"求 lim_{x→0⁻} |x|/x 與 lim_{x→0⁺} |x|/x","steps":["右邊 x > 0：|x| = x，|x|/x = 1，所以右極限是 1。","左邊 x < 0：|x| = −x，|x|/x = −x/x = −1，所以左極限是 −1。","x = 0 本身沒有定義，但這不影響左右極限。"],"answer":"左極限 −1，右極限 1"},{"title":"分段函數的分界點","prompt":"f(x) = x² + 1（x < 1），2x + 3（x ≥ 1）。求 lim_{x→1⁻} f(x)、lim_{x→1⁺} f(x)、f(1)。","steps":["左極限：x < 1 用 x² + 1。x 靠近 1 時靠近 1 + 1 = 2。","右極限：x > 1 用 2x + 3。x 靠近 1 時靠近 2 + 3 = 5。","f(1)：1 屬於 x ≥ 1 那段，f(1) = 5。剛好跟右極限一樣，跟左極限不一樣。"],"answer":"左極限 2，右極限 5，f(1) = 5"},{"title":"取整函數","prompt":"求 lim_{x→2⁻} ⌊x⌋ 與 lim_{x→2⁺} ⌊x⌋","problemId":"lm-fl-003","steps":["x 在 2 的左邊、靠近 2，例如 1.9、1.99、1.999：都在 [1, 2) 裡，⌊x⌋ = 1。","所以 lim_{x→2⁻} ⌊x⌋ = 1。","x 在 2 的右邊、靠近 2，例如 2.01、2.001：都在 [2, 3) 裡，⌊x⌋ = 2，右極限是 2。"],"answer":"左極限 1，右極限 2"}],"pitfalls":["算 x → 2⁻ 卻用了 x ≥ 2 那一段的式子。","把左極限或右極限當成 f(a)。","把 x → 3⁻ 讀成 x → −3。","絕對值沒依正負拆開，就直接約掉。"],"checks":[{"ask":"f(x) = x（x < 2），x + 2（x ≥ 2）。lim_{x→2⁺} f(x) 是？","options":[{"label":"2","why":"那是左極限。右極限要用 x ≥ 2 那段：x + 2 → 4。"},{"label":"不存在","why":"題目只問右邊，右邊穩穩靠近 4，右極限存在。"},{"label":"4","correct":true}]},{"ask":"x → 3⁻ 的意思是？","options":[{"label":"x 從比 3 小的那邊靠近 3","correct":true},{"label":"x 靠近 −3","why":"上標的 − 表示方向，不是負號。"},{"label":"x 從比 3 大的那邊靠近 3","why":"那是 x → 3⁺。"}]},{"ask":"lim_{x→0⁻} |x|/x 是？","options":[{"label":"1","why":"x < 0 時 |x| = −x，比值是 −1；1 是右極限。"},{"label":"−1","correct":true},{"label":"0","why":"0/0 不是 0；而且這裡是先化簡成 −1 再取極限。"}]},{"ask":"lim_{x→2⁻} ⌊x⌋ 是？","options":[{"label":"2","why":"⌊2⌋ = 2 是函數值；在 2 的左邊（例如 1.99）⌊x⌋ = 1。"},{"label":"1.99","why":"⌊x⌋ 永遠是整數。"},{"label":"1","correct":true}]}],"practice":[{"id":"gx-019","core":true},{"id":"gx-020","core":true},{"id":"gp-012","core":true},{"id":"lm-os-001","challenge":true,"note":"挑戰：x → 0⁺ 時 −1/x 往 −∞，e 的很負次方往 0 靠。"}]},"limit-existence":{"id":"limit-existence","prerequisites":["limit-one-sided"],"next":["limit-from-graph-table"],"related":["infinite-limits"],"objectives":["會用「左極限 = 右極限」判斷極限存不存在。","認得極限不存在的三種常見樣子：左右不等、往無窮跑、一直振盪。","會解「參數取多少，極限才存在」這類題目。"],"concept":[{"heading":"① 判準：左右都存在，而且相等","body":["lim_{x→a} f(x) = L 若且唯若 lim_{x→a⁻} f(x) = L 而且 lim_{x→a⁺} f(x) = L。","道理：雙側極限要求「x 夠靠近 a 時 f(x) 就靠近 L」，而 a 的附近同時包含左邊和右邊，兩邊都得靠近同一個 L。"],"tex":["\\lim_{x\\to a}f(x)=L\\iff \\lim_{x\\to a^-}f(x)=L\\ \\text{ 且 }\\ \\lim_{x\\to a^+}f(x)=L"]},{"heading":"② 跟 f(a) 無關","body":["判準裡沒有 f(a)。左右極限都是 2、f(a) = 7，極限照樣是 2；f(a) 沒有定義，極限也可以存在。"]},{"heading":"③ 不存在的三種樣子","body":["左右不等：|x|/x 在 0 的左極限 −1、右極限 1，極限不存在。圖形是跳開的。","往無窮跑：1/x² 在 0 附近要多大有多大，不靠近任何數，極限不存在。習慣上寫 lim_{x→0} 1/x² = ∞，這只是在說明「它怎麼不存在」，∞ 不是一個數（〈無窮極限與垂直漸近線〉）。","振盪：sin(1/x) 在 0 附近不停在 −1 與 1 之間來回，左右兩邊各自都沒有極限。"]},{"heading":"為什麼 sin(1/x) 在 0 沒有極限","body":["取 x = 1/(nπ)（n = 1, 2, 3, …）：這些 x 從右邊靠近 0，而 sin(1/x) = sin(nπ) = 0。","取 x = 2/((4n + 1)π)：這些 x 也從右邊靠近 0，而 sin(1/x) = sin((4n + 1)π/2) = 1。","如果右極限是某個 L，兩串 x 上的值都得靠近 L，但一串一直是 0、一串一直是 1，不可能同時靠近同一個數。所以右極限不存在；左邊同理。"],"collapsible":true},{"heading":"④ 什麼時候要拆兩邊算","body":["函數在 a 的兩側由同一個式子給出、化簡後可以代入：直接算就好。","分段函數的分界點、絕對值裡面為 0 的點、取整函數的整數點：兩側的式子不一樣，一定要分開算再比較。"]}],"workedExamples":[{"title":"絕對值造成左右不等","prompt":"lim_{x→2} (x² − 4)/|x − 2| 存在嗎？","steps":["分子 x² − 4 = (x − 2)(x + 2)。分母有絕對值，分兩邊。","x > 2：|x − 2| = x − 2，式子 = x + 2，右極限 4。","x < 2：|x − 2| = −(x − 2)，式子 = −(x + 2)，左極限 −4。","4 ≠ −4，極限不存在。"],"answer":"不存在（左極限 −4，右極限 4）"},{"title":"左右相等，函數值另外定義","prompt":"f(x) = x² + 1（x < 1），3x − 1（x > 1），f(1) = 7。求 lim_{x→1} f(x)。","steps":["左極限：x² + 1 → 2。","右極限：3x − 1 → 2。","左右都是 2，所以 lim_{x→1} f(x) = 2。f(1) = 7 不影響極限。"],"answer":"2"},{"title":"參數取多少，極限才存在","prompt":"f(x) = kx + 1（x < 2），x² − 1（x ≥ 2）。k 是多少時 lim_{x→2} f(x) 存在？","steps":["右極限：x² − 1 → 4 − 1 = 3。","左極限：kx + 1 → 2k + 1。","要相等：2k + 1 = 3，k = 1。此時極限是 3。"],"answer":"k = 1"}],"pitfalls":["只算一邊就說極限是多少。","看到 f(a) 跟左右極限不一樣，就說極限不存在。","左右不等時取平均當答案。","把 lim = ∞ 當成「極限存在」。","去絕對值時兩邊用了同一個號。"],"checks":[{"ask":"左極限 3、右極限 3、f(a) = 5。lim_{x→a} f(x) 是？","options":[{"label":"3","correct":true},{"label":"不存在","why":"判準只看左右極限；f(a) 是多少都不影響。"},{"label":"5","why":"5 是函數值，不是極限。"}]},{"ask":"左極限 1、右極限 2。lim_{x→a} f(x) 是？","options":[{"label":"1.5","why":"極限不是左右取平均；左右不等，極限就不存在。"},{"label":"不存在","correct":true},{"label":"2","why":"只看了右邊。雙側極限要左右一起。"}]},{"ask":"lim_{x→0} sin(1/x) 是？","options":[{"label":"0","why":"sin(1/x) 不會變小，它一直在 −1 與 1 之間來回擺。"},{"label":"1","why":"只有某些 x 讓 sin(1/x) = 1，也有很多 x 讓它等於 0 或 −1。"},{"label":"不存在（振盪）","correct":true}]},{"ask":"f(x) = |x|/x。lim_{x→0} f(x) 是？","options":[{"label":"不存在","correct":true},{"label":"0","why":"左 −1、右 1。兩者的平均是 0，但極限不是平均。"},{"label":"1","why":"只看了右邊；左邊 x < 0 時比值是 −1。"}]}],"practice":[{"id":"lm-os-005","core":true},{"id":"lm-sq-006","core":true},{"id":"lx-con-001","core":true,"note":"題目問連續；f(2) 由左段給，所以等於要求左右極限相等。"},{"id":"lm-os-002","note":"兩邊都要看：x 是正是負，x² 都是正的。"},{"id":"lm-os-004","challenge":true,"note":"挑戰：x → 0⁺ 時 1/x → ∞，x → 0⁻ 時 1/x → −∞；arctan 在兩端各往哪裡靠？"}]},"limit-from-graph-table":{"id":"limit-from-graph-table","prerequisites":["limit-existence"],"next":["limit-laws-direct"],"related":["infinite-limits","limit-factor"],"objectives":["照固定順序讀圖：左極限、右極限、比較，最後才看 f(a)。","認得四種圖形情況：平滑通過、洞、跳躍、垂直漸近線。","會用數值表估計極限，也知道表格可能騙人。"],"concept":[{"heading":"① 讀圖的順序","body":["先找 x = a 那條鉛直線。從左邊沿著曲線走過去，看高度往哪裡去：那是左極限。從右邊走過去：右極限。兩個一樣，極限就是那個數；不一樣就不存在。","最後才看 x = a 那一點的實心點：那是 f(a)，跟極限是兩件事。"]},{"heading":"② 四種圖形情況","body":["平滑通過：極限等於 f(a)。洞：左右往同一個高度去，極限存在；那一點可能沒定義，也可能另外畫在別處。跳躍：左右高度不同，極限不存在。垂直漸近線：至少一邊往上或往下衝出圖外，極限不存在（〈無窮極限與垂直漸近線〉）。"]},{"heading":"③ 讀表：兩側、越來越近","body":["表格要兩側都有，而且 x 一次比一次靠近 a（例如差 0.1、0.01、0.001）。兩欄都往同一個數靠，就估計那個數是極限。","表格只能估計，不能證明：它只看了有限幾個點。"]},{"heading":"④ 表格會騙人的例子","body":["f(x) = sin(π/x)，取 x = 1、0.1、0.01、0.001：π/x = π、10π、100π、1000π，sin 全部是 0。看起來極限是 0。","但取 x = 2/5、2/9、2/13……（也是往 0 靠）：π/x = 5π/2、9π/2、13π/2，sin 全部是 1。實際上 sin(π/x) 在 0 附近不停振盪，極限不存在。剛好挑到特殊的點，表格就會騙人；之後用代數或定理把極限算出來，才算數。"]}],"workedExamples":[{"title":"用表格估計","prompt":"估計 lim_{x→2} (x³ − 8)/(x − 2)","steps":["x = 2 代不進去（0/0），從兩邊取點。","x = 1.9、1.99、1.999：值 11.41、11.9401、11.994001。","x = 2.1、2.01、2.001：值 12.61、12.0601、12.006001。","兩邊都往 12 靠，估計極限是 12。〈0/0：因式分解〉會用 x³ − 8 = (x − 2)(x² + 2x + 4) 證實它。"],"answer":"12"},{"title":"讀跳躍","prompt":"f 的圖形：x < 1 時是通過 (−1, 0) 與 (1, 2) 的直線，在 (1, 2) 畫空心點；x ≥ 1 時是 y = x − 1，在 (1, 0) 畫實心點。求左右極限、極限與 f(1)。","steps":["左段通過 (−1, 0)、(1, 2)，斜率 1，是 y = x + 1。從左邊走到 x = 1，高度靠近 2：左極限 2。","右段 y = x − 1，從右邊走到 x = 1，高度靠近 0：右極限 0。","2 ≠ 0，lim_{x→1} f(x) 不存在。","實心點在 (1, 0)：f(1) = 0。"],"answer":"左極限 2，右極限 0，極限不存在，f(1) = 0"},{"title":"數字一路變大","prompt":"h(x) = 1/(x − 3)²。從表格判斷 x → 3 時的行為。","steps":["x = 2.99 或 3.01：(x − 3)² = 0.0001，h = 10000。","x = 2.999 或 3.001：(x − 3)² = 0.000001，h = 1000000。","越靠近 3 越大，而且沒有上限：不靠近任何數，極限不存在（往 +∞）。圖形在 x = 3 有垂直漸近線。"],"answer":"不存在，兩側都往 +∞"}],"pitfalls":["把實心點的高度（f(a)）當成極限。","只看一側就下結論。","表格只取兩三個點、或只取特殊的點，就宣稱極限是多少。","垂直漸近線處寫「極限是一個很大的數」。"],"checks":[{"ask":"圖形在 (2, 3) 是空心點，另外在 (2, 1) 有一個實心點，兩側曲線都往 (2, 3) 靠。lim_{x→2} f(x) 是？","options":[{"label":"1","why":"1 是 f(2)，實心點的高度；極限看的是兩側曲線往哪裡去。"},{"label":"3","correct":true},{"label":"不存在","why":"兩側都往 3 靠，極限存在；那一點的值另外定義不影響。"}]},{"ask":"x = 0.9、0.99、0.999 時 f(x) = 4.9、4.99、4.999；x = 1.1、1.01、1.001 時 f(x) = −1.1、−1.01、−1.001。lim_{x→1} f(x)？","options":[{"label":"5","why":"只看了左邊；右邊往 −1 靠。"},{"label":"2","why":"極限不是左右取平均。"},{"label":"不存在","correct":true}]},{"ask":"sin(π/x) 在 x = 1、0.1、0.01、0.001 都是 0。可以下什麼結論？","options":[{"label":"不能下結論；事實上極限不存在","correct":true},{"label":"lim_{x→0} sin(π/x) = 0","why":"只挑了 x = 1/n 這種點；x = 2/5、2/9、2/13 時值都是 1。"},{"label":"lim_{x→0} sin(π/x) = π","why":"π 是 x = 1 時括號裡的數，跟極限無關。"}]},{"ask":"1/(x − 3)² 在 x = 3.01、3.001、3.0001 是 10⁴、10⁶、10⁸。x → 3 時？","options":[{"label":"極限是 10⁸","why":"那只是 x = 3.0001 的值，再靠近會更大。"},{"label":"極限不存在，往 +∞","correct":true},{"label":"極限是 0","why":"是分母 (x − 3)² 往 0 靠，整個分式是往無窮大跑。"}]}],"practice":[{"id":"lx-tab-001","core":true},{"id":"gx-022","core":true},{"id":"gx-019","core":true},{"id":"gx-020","core":true},{"id":"lx-tab-002"}]},"limit-laws-direct":{"id":"limit-laws-direct","prerequisites":["limit-intro","limit-existence"],"next":["limit-factor"],"related":["continuity-definition","infinite-limits","limit-laws-proof"],"objectives":["會用極限定律把一個極限拆成幾塊各自算，並說得出拆之前要確認什麼。","知道多項式、分母不為 0 的有理函數可以直接代入。","代入之前先檢查：得到 0/0、k/0、或在分段函數的分界點，就不能直接代。"],"concept":[{"heading":"① 極限定律：可以拆開算","body":["設 lim_{x→a} f(x) = L、lim_{x→a} g(x) = M 都存在。那麼和、差、常數倍、積、商的極限，等於極限的和、差、常數倍、積、商；商要求 M ≠ 0。","人話：每一塊的極限都存在，就可以各自算再組合。條件「每一塊都存在」不能省（見 ④）。"],"tex":["\\lim(f\\pm g)=L\\pm M,\\quad \\lim(cf)=cL,\\quad \\lim(fg)=LM,\\quad \\lim\\frac{f}{g}=\\frac{L}{M}\\ (M\\neq 0)"]},{"heading":"② 直接代入","body":["lim_{x→a} x = a、lim_{x→a} c = c，再用定律一塊一塊拼，就得到：多項式 p 有 lim_{x→a} p(x) = p(a)；有理函數 p/q 在 q(a) ≠ 0 時有 lim_{x→a} p(x)/q(x) = p(a)/q(a)。","根號、eˣ、ln x、sin x、cos x 在它們的定義域裡也可以直接代入。「可以直接代入」有個名字，叫連續（〈連續的定義〉）。"]},{"heading":"③ 代入之前先檢查","body":["代進去分母不是 0：直接代，完成。","得到 0/0：商定律不能用（分母極限是 0），但極限可能存在，要先化簡，下一課開始處理。","得到 k/0（k ≠ 0）：分子靠近 k、分母靠近 0，值會爆掉（〈無窮極限與垂直漸近線〉）。","分段函數的分界點：兩側式子不同，要分左右算。"]},{"heading":"④ 拆不開的時候","body":["lim_{x→0} (1/x − 1/x)：x ≠ 0 時式子恆等於 0，所以極限是 0。但不能拆成 lim 1/x − lim 1/x，因為 lim_{x→0} 1/x 不存在。拆不開時先化簡，或換別的方法。","這些定律的嚴格證明要用 ε-δ 的語言，見〈極限定律〉；這裡先會用。"]}],"workedExamples":[{"title":"多項式","prompt":"lim_{x→2} (3x² − 5x + 1)","steps":["多項式，處處可以直接代入。","3 · 2² − 5 · 2 + 1 = 12 − 10 + 1 = 3。"],"answer":"3"},{"title":"有理函數：先看分母","prompt":"lim_{x→−1} (x² + 2x + 3)/(x − 4)","steps":["分母在 x = −1：−1 − 4 = −5 ≠ 0，可以直接代。","分子：(−1)² + 2(−1) + 3 = 1 − 2 + 3 = 2。","極限 = 2/(−5) = −2/5。"],"answer":"−2/5"},{"title":"根號與分式組合","prompt":"lim_{x→4} √(2x + 1)/(x − 1)","steps":["分母在 4：4 − 1 = 3 ≠ 0。根號裡在 4：2 · 4 + 1 = 9 > 0，在定義域內。","分子極限：√9 = 3。分母極限：3。","商定律：3/3 = 1。"],"answer":"1"},{"title":"代進去是 0/0：停下來","prompt":"lim_{x→1} (x² − 1)/(x − 1) 可以直接代入嗎？","steps":["分母在 1 是 0，商定律不能用；分子在 1 也是 0，是 0/0。","0/0 不是答案，也不代表極限不存在；它代表要先化簡。","（下一課：x ≠ 1 時 (x² − 1)/(x − 1) = x + 1，極限是 2。）"],"answer":"不能直接代入；先化簡，極限是 2"}],"pitfalls":["分母極限是 0 還硬用商定律。","把極限拆成兩個不存在的極限再相減。","代入得 0/0 就寫答案 0，或寫「不存在」。","在分段函數的分界點直接代某一段的式子。","在定義域外面代入：√x 在 x = −1 附近根本沒有定義，談不上 lim_{x→−1} √x。"],"checks":[{"ask":"lim_{x→3} (x² − 1)/(x + 1) 是？","options":[{"label":"8","why":"8 只是分子；分母也要代：3 + 1 = 4，8/4 = 2。"},{"label":"2","correct":true},{"label":"不存在","why":"分母在 3 是 4 ≠ 0，可以直接代入。"}]},{"ask":"下面哪一個可以直接代入？","options":[{"label":"lim_{x→1} (x² − 1)/(x − 1)","why":"代入得 0/0，要先化簡。"},{"label":"lim_{x→−1} (x + 2)/(x + 1)","why":"分母在 −1 是 0、分子是 1，是 k/0 型，不能直接代。"},{"label":"lim_{x→1} (x + 2)/(x + 1)","correct":true}]},{"ask":"lim f = 3、lim g = −2（x → a）。lim (2f − g²)/(f + g) 是？","options":[{"label":"2","correct":true},{"label":"10","why":"g² 是 (−2)² = 4，不是 −4。正確是 (6 − 4)/1 = 2。"},{"label":"2/5","why":"分母是 f + g = 3 + (−2) = 1，不是 3 − (−2) = 5。"}]},{"ask":"lim_{x→0} (1/x − 1/x) 是？","options":[{"label":"不存在，因為 lim 1/x 不存在","why":"x ≠ 0 時式子恆等於 0；不能拆開時要先化簡，而不是放棄。"},{"label":"0","correct":true},{"label":"∞ − ∞，無法決定","why":"這不是兩個極限相減的問題；化簡後是常數 0。"}]}],"practice":[{"id":"cx-lim-001","core":true},{"id":"fd-lim-001","core":true},{"id":"fd-lim-002","core":true},{"id":"tmpl-lim-direct-002"}]},"limit-factor":{"id":"limit-factor","prerequisites":["limit-laws-direct","polynomial-rational"],"next":["limit-rationalize"],"related":["infinite-limits"],"objectives":["知道代入得 0/0 的有理函數，分子分母一定有共同因式 (x − a)。","會因式分解、約掉 (x − a)、再代入；約完還是 0/0 就再約一次。","說得出為什麼可以約：極限只看 x ≠ a 的地方。"],"concept":[{"heading":"① 0/0 是一個訊號","body":["lim_{x→2} (x² − 4)/(x − 2)：代入得 0/0。0/0 不是一個數，它不是答案，也不代表極限不存在。","對多項式來說，它在告訴你一件具體的事：分子分母在 x = 2 都是 0，由因式定理（〈多項式與有理函數〉），兩者都有 (x − 2) 這個因式。"]},{"heading":"② 約掉造成 0 的因式","body":["x² − 4 = (x − 2)(x + 2)。x 靠近 2 但不等於 2，所以 x − 2 ≠ 0，可以約：(x² − 4)/(x − 2) = x + 2（x ≠ 2）。","為什麼約完的極限一樣：兩個函數只在 x = 2 這一點不同（一個沒定義、一個是 4），而極限完全不看那一點。所以 lim_{x→2} (x² − 4)/(x − 2) = lim_{x→2} (x + 2) = 4。"],"tex":["\\lim_{x\\to2}\\frac{x^2-4}{x-2}=\\lim_{x\\to2}\\frac{(x-2)(x+2)}{x-2}=\\lim_{x\\to2}(x+2)=4"]},{"heading":"③ 常用的分解","body":["平方差 a² − b² = (a − b)(a + b)；立方差 a³ − b³ = (a − b)(a² + ab + b²)；二次式用十字交乘。","看不出來時，已知 x = a 是根，就用長除法或比較係數把 (x − a) 除出來。"]},{"heading":"④ 約完還沒完","body":["約一次之後再代入。還是 0/0：分子分母還有 (x − a)，再約一次（重根）。","分母變成非 0：直接代，得到答案。","分母還是 0、分子不是 0：k/0 型，極限是 ±∞ 或左右不同號而不存在（〈無窮極限與垂直漸近線〉）。"]}],"workedExamples":[{"title":"二次式","prompt":"lim_{x→3} (x² − x − 6)/(x − 3)","problemId":"fd-lim-003","steps":["代 x = 3：9 − 3 − 6 = 0，分母 0，是 0/0。所以分子有 (x − 3) 這個因式。","十字交乘：x² − x − 6 = (x − 3)(x + 2)。","x ≠ 3，約掉 x − 3，剩 x + 2。","代 x = 3：5。"],"answer":"5"},{"title":"立方差與平方差","prompt":"lim_{x→1} (x³ − 1)/(x² − 1)","problemId":"lec-01-q1b","steps":["代 x = 1：0/0。","分子立方差：x³ − 1 = (x − 1)(x² + x + 1)。分母平方差：x² − 1 = (x − 1)(x + 1)。","約掉 x − 1：(x² + x + 1)/(x + 1)。","代 x = 1：3/2。"],"answer":"3/2"},{"title":"要約兩次","prompt":"lim_{x→1} (x³ − 3x + 2)/(x² − 2x + 1)","steps":["代 x = 1：分子 1 − 3 + 2 = 0，分母 1 − 2 + 1 = 0。","分子除以 (x − 1)：x³ − 3x + 2 = (x − 1)(x² + x − 2)。x² + x − 2 在 1 也是 0，再拆：(x − 1)(x + 2)。所以分子 = (x − 1)²(x + 2)。","分母 = (x − 1)²。","約掉 (x − 1)²：剩 x + 2，代 x = 1 得 3。只約一次會得到 (x − 1)(x + 2)/(x − 1)²，代入仍是 0/0。"],"answer":"3"}],"pitfalls":["把 0/0 當成 0 或 1。","立方差中間項的號寫錯：x³ − 8 = (x − 2)(x² + 2x + 4)，第二個因式全是加號。","約分之後又代回原式，再得到一次 0/0。","約一次還是 0/0 就說極限不存在。","分解號錯：x² − x − 6 寫成 (x + 3)(x − 2)。展開檢查一次就抓得到。"],"checks":[{"ask":"lim_{x→4} (x² − 16)/(x − 4) 是？","options":[{"label":"0","why":"代入得 0/0 不是答案。約掉 x − 4 後是 x + 4，代 4 得 8。"},{"label":"4","why":"約完剩 x + 4，不是 x；代 4 得 8。"},{"label":"8","correct":true}]},{"ask":"x³ − 8 的因式分解是？","options":[{"label":"(x − 2)(x² + 2x + 4)","correct":true},{"label":"(x − 2)(x² − 2x + 4)","why":"立方差 a³ − b³ 的第二個因式全是加號；中間是 −2x 的是立方和 x³ + 8 的分解。"},{"label":"(x − 2)(x² + 4)","why":"展開是 x³ − 2x² + 4x − 8，多了 −2x² + 4x。"}]},{"ask":"lim_{x→2} (x³ − 8)/(x − 2) 是？","options":[{"label":"4","why":"約完是 x² + 2x + 4，代 2 是 4 + 4 + 4 = 12。"},{"label":"12","correct":true},{"label":"0","why":"0/0 不是 0。"}]},{"ask":"lim_{x→−1} (x² − 1)/(x² + 2x + 1) 是？","options":[{"label":"1","why":"分子 (x − 1)(x + 1)、分母 (x + 1)²，約完是 (x − 1)/(x + 1)，不是 1。"},{"label":"0","why":"約完分子 → −2、分母 → 0，是 k/0 型，不是 0。"},{"label":"不存在","correct":true}]}],"practice":[{"id":"cx-lim-002","core":true},{"id":"fd-lim-004","core":true},{"id":"lim-003","core":true},{"id":"cx-lim-009","core":true},{"id":"tmpl-lim-factor-002"},{"id":"tb-lh-003","challenge":true,"note":"挑戰：x⁵ − 1 = (x − 1)(x⁴ + x³ + x² + x + 1)，跟立方差同一個道理。"},{"id":"lx-con-003","challenge":true,"note":"挑戰：要有洞，分子在 x = 3 也得是 0。"}]},"limit-rationalize":{"id":"limit-rationalize","prerequisites":["limit-factor"],"next":["limit-algebra-other"],"related":[],"objectives":["看到「根號減一個數」造成 0/0，知道要乘共軛。","會處理三種情況：根號在分子、兩個根號相減、x → ∞ 的 ∞ − ∞。","化簡之後再代入，不在 0/0 的狀態下代。"],"concept":[{"heading":"① 因式分解不夠用的時候","body":["lim_{x→0} (√(x + 9) − 3)/x：代 x = 0 得 0/0。","上一課的辦法是因式分解、約掉造成 0 的因子。但 √(x + 9) − 3 不是多項式，拆不出 x 這個因子。我們需要把根號「趕出去」。"]},{"heading":"② 共軛：利用平方差把根號消掉","body":["平方差公式 (A − B)(A + B) = A² − B²。如果 A 是根號，A² 就沒有根號了：(√(x + 9) − 3)(√(x + 9) + 3) = (x + 9) − 9 = x。","√(x + 9) + 3 叫做 √(x + 9) − 3 的「共軛」。乘上共軛，根號消失，而且剛好冒出我們要的因子 x。"],"tex":["\\left(\\sqrt{x+9}-3\\right)\\left(\\sqrt{x+9}+3\\right)=(x+9)-9=x"]},{"heading":"③ 為什麼可以乘：分子分母同乘一樣的東西","body":["分子分母同乘 √(x + 9) + 3，等於乘 1，值不變。它在 x 靠近 0 時約等於 6，不是 0，所以可以放心乘：(√(x + 9) − 3)/x = 1/(√(x + 9) + 3)（x ≠ 0）。","現在可以代了：1/(3 + 3) = 1/6。"]},{"heading":"④ 三種常見樣子","body":["根號在分子：(√(x + a) − √a)/x，乘 √(x + a) + √a。","兩個根號相減：(√(1 + x) − √(1 − x))/x，乘 √(1 + x) + √(1 − x)。","x → ∞ 的 ∞ − ∞：√(x² + 4x) − x，看成分母是 1 的分式，一樣乘共軛；之後要把 x 從根號裡提出來（範例 3）。"]},{"heading":"⑤ 有理化之後，常常還要再做一件事","body":["乘完共軛只是把 0/0（或 ∞ − ∞）變成能處理的樣子，最後還是要約分，或同除以最高次，才能代入。"]}],"workedExamples":[{"title":"根號在分子","prompt":"lim_{x→0} (√(x + 9) − 3)/x","problemId":"cx-lim-005","steps":["代 x = 0 得 0/0。根號減一個數 → 乘共軛 √(x + 9) + 3。","分子 (√(x + 9) − 3)(√(x + 9) + 3) = x + 9 − 9 = x。","式子變成 x / ( x(√(x + 9) + 3) )。x ≠ 0，約掉 x，剩 1/(√(x + 9) + 3)。","代 x = 0：1/(3 + 3) = 1/6。"],"answer":"1/6"},{"title":"兩個根號相減","prompt":"lim_{x→0} (√(1 + x) − √(1 − x))/x","problemId":"cx-exam-001","steps":["代 x = 0 得 0/0。乘共軛 √(1 + x) + √(1 − x)。","分子 (1 + x) − (1 − x) = 2x。","式子變成 2x / ( x(√(1 + x) + √(1 − x)) ) = 2/(√(1 + x) + √(1 − x))。","代 x = 0：2/(1 + 1) = 1。"],"answer":"1"},{"title":"x → ∞ 的 ∞ − ∞","prompt":"lim_{x→∞} (√(x² + 4x) − x)","problemId":"cx-lim-006","steps":["兩項都往 ∞ 跑，∞ − ∞ 不能直接說是 0。看成分母是 1 的分式，乘共軛 √(x² + 4x) + x。","分子 (x² + 4x) − x² = 4x，式子變成 4x/(√(x² + 4x) + x)。","把 x 從根號裡提出來。x → ∞，可以只看 x > 0：√(x² + 4x) = √(x²(1 + 4/x)) = √(x²) · √(1 + 4/x) = x√(1 + 4/x)（x > 0 時 √(x²) = x）。","式子變成 4x/(x√(1 + 4/x) + x)，分子分母同除以 x：4/(√(1 + 4/x) + 1)。","x → ∞ 時 4/x → 0，得 4/(1 + 1) = 2。"],"answer":"2"}],"pitfalls":["只有分子乘共軛，分母沒乘。","把 √(x + 9) 拆成 √x + 3。根號不能拆加法。","把 ∞ − ∞ 直接當 0。","把 √(x²) 直接寫成 x，忘了它其實是 |x|（x → −∞ 時要寫 −x）。","乘完共軛就停了，沒有約分就代入，又得到 0/0。"],"checks":[{"ask":"lim_{x→0} (√(1 + x) − 1)/x 要乘什麼？","options":[{"label":"√(1 + x) + 1","correct":true},{"label":"√(1 + x) − 1","why":"乘自己會得到平方，根號還在交叉項裡，消不掉。"},{"label":"x","why":"乘 x 不會讓根號消失，0/0 還在。"}]},{"ask":"承上題，極限是？","options":[{"label":"1/2","correct":true},{"label":"0","why":"0/0 不是 0。化簡後是 1/(√(1 + x) + 1)，代 0 得 1/2。"},{"label":"1","why":"分母的共軛也有一個 1：1/(1 + 1) = 1/2。"}]},{"ask":"lim_{x→∞} (√(x² + 4x) − x) 是？","options":[{"label":"2","correct":true},{"label":"0","why":"∞ − ∞ 不能直接當 0。乘共軛之後是 4x/(√(x² + 4x) + x) → 2。"},{"label":"4","why":"同除以 x 之後分母是 √(1 + 4/x) + 1 → 2，不是 1。"}]},{"ask":"x > 0 時，√(x² + 4x) 等於？","options":[{"label":"x√(1 + 4/x)","correct":true},{"label":"x + 2","why":"根號不能拆加法；x + 2 平方是 x² + 4x + 4，多了 4。"},{"label":"x²√(1 + 4/x)","why":"從根號裡提出 x² 會變成 x，不是 x²。"}]}],"practice":[{"id":"rel-basic-005","core":true},{"id":"fd-lim-011","core":true},{"id":"cx-lim-006","core":true},{"id":"lim-037","core":true},{"id":"cx-exam-001","core":true},{"id":"lim-022","core":true},{"id":"lx-der-002"},{"id":"lx-hard-001","challenge":true,"note":"挑戰：立方根不能用平方根的共軛，要用 a³ − b³ = (a − b)(a² + ab + b²)。"}]},"limit-algebra-other":{"id":"limit-algebra-other","prerequisites":["limit-factor","limit-rationalize"],"next":["limit-trig-standard"],"related":["derivative-definition"],"objectives":["會處理繁分式：先把分子通分，再約掉造成 0 的因式。","會展開 (a + h)ⁿ 這類式子，把 h 提出來約掉。","看到兩個分式相減的 ∞ − ∞，會先通分；看到立方根，會換元。"],"concept":[{"heading":"① 目標都一樣：把造成 0 的因式找出來","body":["〈0/0：因式分解〉與〈0/0：有理化〉處理了多項式和平方根。這一課是另外幾種常見的樣子。招式不同，但最後一步都一樣：讓 (x − a) 或 h 這個因式現身，約掉，再代入。"]},{"heading":"② 繁分式：先通分","body":["lim_{x→3} (1/x − 1/3)/(x − 3)。分子是兩個分數相減，先通分：1/x − 1/3 = (3 − x)/(3x)。","整個式子變成 (3 − x)/(3x(x − 3))。注意 3 − x = −(x − 3)，約掉後剩 −1/(3x)，代入得 −1/9。"]},{"heading":"③ 展開：讓 h 冒出來","body":["lim_{h→0} ((3 + h)² − 9)/h。展開 (3 + h)² = 9 + 6h + h²，減 9 之後每一項都有 h：6h + h² = h(6 + h)。約掉 h 得 6 + h → 6。","這種式子在〈導數定義〉裡天天出現：它其實是 x² 在 x = 3 的切線斜率。"]},{"heading":"④ 兩個分式相減：∞ − ∞ 先通分","body":["lim_{x→1} (1/(x − 1) − 2/(x² − 1))：兩項各自都在爆，但不能說 ∞ − ∞ = 0。通分成一個分式，往往就變成 0/0，再用因式分解。"]},{"heading":"⑤ 換元：把根號換成新變數","body":["立方根沒有「平方根的共軛」可以用。令 t = ∛x，則 x = t³，式子變成 t 的有理函數。","換元時，極限的去處也要跟著換：x → 1 時 t = ∛x → 1；x → 8 時 t → 2。"]}],"workedExamples":[{"title":"繁分式","prompt":"lim_{x→3} (1/x − 1/3)/(x − 3)","steps":["代入：分子 1/3 − 1/3 = 0，分母 0，是 0/0。","分子通分：1/x − 1/3 = (3 − x)/(3x)。","整個式子 = (3 − x)/(3x) ÷ (x − 3) = (3 − x)/(3x(x − 3))。","3 − x = −(x − 3)，約掉（x ≠ 3）：−1/(3x)。代 x = 3：−1/9。"],"answer":"−1/9"},{"title":"展開","prompt":"lim_{h→0} ((2 + h)³ − 8)/h","problemId":"db-def-001","steps":["代 h = 0：0/0。","展開：(2 + h)³ = 8 + 12h + 6h² + h³。減 8：12h + 6h² + h³ = h(12 + 6h + h²)。","h ≠ 0，約掉 h：12 + 6h + h²。","代 h = 0：12。"],"answer":"12"},{"title":"∞ − ∞：通分","prompt":"lim_{x→1} (1/(x − 1) − 2/(x² − 1))","steps":["x → 1 時兩項都爆掉，不能直接相減。","x² − 1 = (x − 1)(x + 1) 是公分母：1/(x − 1) = (x + 1)/(x² − 1)。","相減：(x + 1 − 2)/(x² − 1) = (x − 1)/((x − 1)(x + 1)) = 1/(x + 1)（x ≠ 1）。","代 x = 1：1/2。"],"answer":"1/2"},{"title":"立方根：換元","prompt":"lim_{x→1} (∛x − 1)/(x − 1)","steps":["令 t = ∛x，x = t³。x → 1 時 t → 1。","式子變成 (t − 1)/(t³ − 1)。","立方差 t³ − 1 = (t − 1)(t² + t + 1)，約掉 t − 1：1/(t² + t + 1)。","代 t = 1：1/3。"],"answer":"1/3"}],"pitfalls":["通分時分子的號弄反：1/x − 1/3 = (3 − x)/(3x)，不是 (x − 3)/(3x)。","把 (3 − x)/(x − 3) 約成 1；它等於 −1。","把 (2 + h)³ 展開成 8 + h³。","看到 ∞ − ∞ 就寫 0。","換元之後，極限還寫 x → 8 而不是 t → 2。"],"checks":[{"ask":"1/x − 1/3 通分後是？","options":[{"label":"(x − 3)/(3x)","why":"號反了：1/x = 3/(3x)，1/3 = x/(3x)，相減是 (3 − x)/(3x)。"},{"label":"(3 − x)/(3x)","correct":true},{"label":"1/(x − 3)","why":"分數相減不能把分母直接相減。"}]},{"ask":"x ≠ 3 時，(3 − x)/(x − 3) 等於？","options":[{"label":"−1","correct":true},{"label":"1","why":"3 − x = −(x − 3)，約完留下一個負號。"},{"label":"0","why":"分子分母都不是 0（x ≠ 3），比值是 −1。"}]},{"ask":"lim_{h→0} ((1 + h)² − 1)/h 是？","options":[{"label":"1","why":"(1 + h)² = 1 + 2h + h²，不是 1 + h²；減 1 除以 h 是 2 + h → 2。"},{"label":"0","why":"代入得 0/0，不是 0；要先展開約掉 h。"},{"label":"2","correct":true}]},{"ask":"求 lim_{x→8} (∛x − 2)/(x − 8)，令 t = ∛x。t 趨近多少？","options":[{"label":"8","why":"x 往 8 靠，t = ∛x 往 ∛8 = 2 靠。"},{"label":"2","correct":true},{"label":"0","why":"t 是 ∛x，不是 ∛x − 2。"}]}],"practice":[{"id":"lx-der-001","core":true},{"id":"lx-hard-001","core":true,"note":"令 t = ∛x，x → 8 時 t → 2。"},{"id":"dd-def-002","challenge":true,"note":"挑戰：不必整個展開。a¹⁰ − b¹⁰ = (a − b)(a⁹ + a⁸b + … + b⁹)，取 a = 2 + h、b = 2。"}]},"limit-trig-standard":{"id":"limit-trig-standard","prerequisites":["limit-laws-direct","trig-functions","trig-identities"],"next":["limit-exp-log-standard"],"related":["squeeze-theorem","derivative-trig"],"objectives":["知道 lim_{x→0} sin x / x = 1，而且 x 要用弧度。","會把 sin(ax)/(bx)、tan(ax)/(bx) 這類式子「配」成標準形，得到 a/b。","會算 lim_{x→0} (1 − cos x)/x² = 1/2，並知道它是怎麼由 sin x / x 推出來的。"],"concept":[{"heading":"① 代不進去，但表格很清楚","body":["lim_{x→0} sin x / x：代入得 0/0，而 sin x 不是多項式，前幾課的化簡都不能用。","先看數字：x = 0.1 時 sin x / x ≈ 0.998334，x = 0.01 時 ≈ 0.99998333，x = 0.001 時 ≈ 0.9999998。x 換成負的，值完全一樣（sin x / x 是偶函數）。它往 1 靠。"],"tex":["\\lim_{x\\to0}\\frac{\\sin x}{x}=1"]},{"heading":"② 直覺：x 很小時 sin x 幾乎就是 x","body":["在單位圓上，角 x 很小時，弧長 x 和高度 sin x 幾乎一樣長。這是直覺，不是證明：「幾乎一樣」到底多接近、為什麼比值剛好趨近 1，需要下面的不等式。","x 一定要用弧度。用角度的話，sin(1°) ≈ 0.017452，跟 1 差很遠；比值會變成 π/180。"]},{"heading":"證明（用面積夾出來）","body":["先看 0 < x < π/2。單位圓上取角 x：以原點、(1, 0)、(cos x, sin x) 為頂點的三角形面積是 ½ sin x；同一個角的扇形面積是 ½ x（這一步用到弧度：扇形面積 = ½ · 半徑² · 弧度）；以原點、(1, 0)、(1, tan x) 為頂點的三角形面積是 ½ tan x。三塊一塊包住一塊，所以 sin x < x < tan x。","全部除以 sin x（> 0）：1 < x / sin x < 1/cos x，取倒數得 cos x < sin x / x < 1。","x → 0⁺ 時 cos x → 1，sin x / x 被夾在往 1 靠的 cos x 與常數 1 之間，所以右極限是 1（〈夾擠定理〉）。sin x / x 是偶函數，左極限一樣是 1。","這個證明只用到面積與 cos 的連續性，沒有用到 sin 的導數，所以之後〈三角函數微分〉拿它來推 (sin x)′ = cos x 不會循環論證。"],"collapsible":true},{"heading":"③ 配湊：分母要跟 sin 裡面一樣","body":["sin(5x)/(3x)：sin 裡面是 5x，分母要配成 5x。寫成 (5/3) · sin(5x)/(5x)。x → 0 時 5x → 0，所以 sin(5x)/(5x) → 1，答案 5/3。一般地，sin(ax)/(bx) → a/b。","tan x / x = (sin x / x) · (1/cos x) → 1 · 1 = 1，所以 tan 也能照樣配。"]},{"heading":"④ 第二個標準極限：(1 − cos x)/x² → 1/2","body":["分子分母同乘 1 + cos x（x 靠近 0 時它靠近 2，不是 0）：(1 − cos x)(1 + cos x) = 1 − cos²x = sin²x。","所以 (1 − cos x)/x² = (sin x / x)² · 1/(1 + cos x) → 1² · 1/2 = 1/2。順帶得到 (1 − cos x)/x = x · (1 − cos x)/x² → 0。"],"tex":["\\lim_{x\\to0}\\frac{1-\\cos x}{x^2}=\\frac12"]}],"workedExamples":[{"title":"配係數","prompt":"lim_{x→0} sin(5x)/(3x)","steps":["代入是 0/0。sin 裡面是 5x，把分母配成 5x。","sin(5x)/(3x) = (5/3) · sin(5x)/(5x)。","x → 0 時 5x → 0，sin(5x)/(5x) → 1。","答案 5/3。"],"answer":"5/3"},{"title":"tan 與 sin 混合","prompt":"lim_{x→0} tan(2x)/sin(3x)","steps":["拆成三塊：tan(2x)/sin(3x) = [tan(2x)/(2x)] · [3x/sin(3x)] · (2x/3x)。","tan(2x)/(2x) → 1，3x/sin(3x) → 1，2x/3x = 2/3。","相乘：2/3。"],"answer":"2/3"},{"title":"1 − cos 的配湊","prompt":"lim_{x→0} (1 − cos 4x)/x²","problemId":"tmpl-lim-cos-square-002","steps":["標準形是 (1 − cos u)/u² → 1/2，這裡 u = 4x，分母要配成 (4x)² = 16x²。","(1 − cos 4x)/x² = 16 · (1 − cos 4x)/(4x)²。","x → 0 時 4x → 0，(1 − cos 4x)/(4x)² → 1/2。","答案 16 · 1/2 = 8。"],"answer":"8"}],"pitfalls":["sin(5x)/x 直接寫 1：分母要配成 5x，答案是 5。","以為 lim_{x→∞} sin x / x 也是 1；它是 0，標準極限只在 x → 0。","(1 − cos 4x)/x² 配係數時只乘 4，忘了平方。","用角度算：sin x° / x 的極限是 π/180，不是 1。"],"checks":[{"ask":"lim_{x→0} sin(3x)/x 是？","options":[{"label":"1","why":"分母要是 3x 才是 1；這裡分母只有 x，配完多一個 3。"},{"label":"3","correct":true},{"label":"1/3","why":"倒過來了：sin(3x)/x = 3 · sin(3x)/(3x)。"}]},{"ask":"lim_{x→∞} sin x / x 是？","options":[{"label":"1","why":"sin x / x → 1 只在 x → 0。x → ∞ 時分子在 −1 與 1 之間，分母越來越大。"},{"label":"不存在","why":"sin x 雖然振盪，但被 1/x 壓到 0：|sin x / x| ≤ 1/x。"},{"label":"0","correct":true}]},{"ask":"lim_{x→0} (1 − cos x)/x² 是？","options":[{"label":"1/2","correct":true},{"label":"0","why":"1 − cos x 跟 x² 一樣快趨近 0，比值不是 0。只有 (1 − cos x)/x 才 → 0。"},{"label":"1","why":"同乘 1 + cos x 之後，多出一個 1/(1 + cos x) → 1/2。"}]},{"ask":"lim_{x→0} sin(x²)/x 是？","options":[{"label":"1","why":"sin 裡面是 x²，分母要配成 x²：sin(x²)/x = x · sin(x²)/x² → 0 · 1。"},{"label":"0","correct":true},{"label":"不存在","why":"拆成 x · sin(x²)/x² 之後，兩塊的極限都存在。"}]}],"practice":[{"id":"lim-001","core":true},{"id":"cx-lim-004","core":true},{"id":"fd-lim-005","core":true},{"id":"fd-lim-006","core":true},{"id":"fd-lim-012","core":true},{"id":"lim-002","core":true},{"id":"exam-lim-005","core":true},{"id":"lim-007"},{"id":"lim-030"},{"id":"lim-015","challenge":true,"note":"挑戰：sec x − 1 = (1 − cos x)/cos x。"},{"id":"depth-lim-010","challenge":true,"note":"挑戰：分子分母各自配成標準形。"}]},"limit-exp-log-standard":{"id":"limit-exp-log-standard","prerequisites":["limit-trig-standard","exp-log"],"next":["limit-e-type"],"related":[],"objectives":["知道 lim_{x→0} (eˣ − 1)/x = 1 與 lim_{x→0} ln(1 + x)/x = 1。","會配湊出 (e^{ax} − 1)/(bx) → a/b、ln(1 + ax)/(bx) → a/b，以及 (aˣ − 1)/x → ln a。","會用 t = 1/x 把 x → ∞ 的式子換成 t → 0 的標準形。"],"concept":[{"heading":"① 兩個新的標準極限","body":["x = 0.01 時，(eˣ − 1)/x ≈ 1.005017，ln(1 + x)/x ≈ 0.995033；x = −0.01 時分別是 0.995017 與 1.005034。兩邊都往 1 靠。"],"tex":["\\lim_{x\\to0}\\frac{e^x-1}{x}=1,\\qquad \\lim_{x\\to0}\\frac{\\ln(1+x)}{x}=1"]},{"heading":"② 直覺：靠近 0 時 eˣ ≈ 1 + x、ln(1 + x) ≈ x","body":["eˣ 在 (0, 1) 的切線是 y = 1 + x，斜率剛好是 1。曲線在切點附近看起來就是切線，所以 eˣ − 1 ≈ x，比值靠近 1。ln(1 + x) 是它的反函數，切線是 y = x。","這是直覺，不是證明：它假設了「eˣ 在 0 的切線斜率是 1」，而那正是要證的事。有些課本直接拿這件事當 e 的定義；從 e = lim (1 + 1/n)ⁿ（〈e 型極限〉）出發也證得出來，但要多一些功夫，這裡先接受第一條。"]},{"heading":"由第一條推出第二條","body":["令 u = ln(1 + x)，則 x = eᵘ − 1。x → 0 時 u = ln(1 + x) → ln 1 = 0（ln 連續），而且 x ≠ 0 時 u ≠ 0。","所以 ln(1 + x)/x = u/(eᵘ − 1) = 1 / ((eᵘ − 1)/u) → 1/1 = 1。"],"collapsible":true},{"heading":"③ 配湊","body":["跟三角一樣：指數上、ln 裡面是什麼，分母就配成什麼。(e^{3x} − 1)/(2x) = (3/2) · (e^{3x} − 1)/(3x) → 3/2。一般地 (e^{ax} − 1)/(bx) → a/b，ln(1 + ax)/(bx) → a/b。","其他底數先換成 e：aˣ = e^{x ln a}，所以 (aˣ − 1)/x = ln a · (e^{x ln a} − 1)/(x ln a) → ln a。"]},{"heading":"④ x → ∞ 的版本","body":["x ln(1 + 2/x)：x → ∞ 時 ln 那項 → 0、x → ∞，是 ∞ · 0 型。令 t = 1/x，x → ∞ 時 t → 0⁺，式子變成 ln(1 + 2t)/t → 2。"]}],"workedExamples":[{"title":"配係數","prompt":"lim_{x→0} (e^{3x} − 1)/(2x)","steps":["代入是 0/0。指數上是 3x，分母配成 3x。","(e^{3x} − 1)/(2x) = (3/2) · (e^{3x} − 1)/(3x)。","x → 0 時 3x → 0，(e^{3x} − 1)/(3x) → 1。答案 3/2。"],"answer":"3/2"},{"title":"底數不是 e","prompt":"lim_{x→0} (2ˣ − 1)/x","problemId":"world-002","steps":["換成 e：2ˣ = e^{x ln 2}。","(2ˣ − 1)/x = ln 2 · (e^{x ln 2} − 1)/(x ln 2)。","x → 0 時 x ln 2 → 0，後面那塊 → 1。答案 ln 2 ≈ 0.693。"],"answer":"ln 2"},{"title":"x → ∞ 換成 t → 0","prompt":"lim_{x→∞} x ln(1 + 2/x)","problemId":"lim-040","steps":["∞ · 0 型，不能直接判斷。令 t = 1/x，x → ∞ 時 t → 0⁺。","x ln(1 + 2/x) = ln(1 + 2t)/t。","配湊：ln(1 + 2t)/t = 2 · ln(1 + 2t)/(2t) → 2。"],"answer":"2"}],"pitfalls":["(e^{3x} − 1)/x 寫成 1，忘了配出 3。","把 (aˣ − 1)/x 的答案寫成 a；正確是 ln a。","ln(1 + 2x) 拆成 ln 1 + ln 2x。","∞ · 0 直接當 0。","把 x → ∞ 的式子直接套 x → 0 的標準形，沒有先換元。"],"checks":[{"ask":"lim_{x→0} (e^{5x} − 1)/x 是？","options":[{"label":"1","why":"分母要是 5x 才是 1；這裡要配出一個 5。"},{"label":"e⁵","why":"x → 0 時 e^{5x} → 1，答案跟 e⁵ 無關；配湊後是 5。"},{"label":"5","correct":true}]},{"ask":"lim_{x→0} ln(1 + 3x)/(2x) 是？","options":[{"label":"3/2","correct":true},{"label":"2/3","why":"倒過來了：ln 裡面的係數 3 在分子。"},{"label":"3","why":"分母還有 2：3/2。"}]},{"ask":"lim_{x→0} (3ˣ − 1)/x 是？","options":[{"label":"3","why":"3ˣ = e^{x ln 3}，配出來的係數是 ln 3。"},{"label":"ln 3","correct":true},{"label":"1","why":"只有底數是 e 時才是 1。"}]},{"ask":"lim_{x→∞} x ln(1 + 1/x) 是？","options":[{"label":"0","why":"ln 那項 → 0，但 x → ∞，是 ∞ · 0 型，不能直接說 0。令 t = 1/x 得 ln(1 + t)/t → 1。"},{"label":"1","correct":true},{"label":"∞","why":"ln(1 + 1/x) 跟 1/x 一樣快趨近 0，乘上 x 剛好抵消。"}]}],"practice":[{"id":"lim-005","core":true},{"id":"fd-lim-009","core":true},{"id":"rel-basic-003","core":true},{"id":"fd-lim-010","core":true},{"id":"rel-basic-004","core":true},{"id":"tmpl-lim-log-ratio-001","core":true},{"id":"exam-lim-019","core":true,"note":"先合併：ln(x + 1) − ln x = ln(1 + 1/x)。"},{"id":"lim-006"},{"id":"tb-lh-004","note":"拆成 (4ˣ − 1)/x − (2ˣ − 1)/x。"},{"id":"exam-lim-015","challenge":true,"note":"挑戰：寫成 (e^{sin x} − 1)/sin x · sin x / x。"}]},"limit-e-type":{"id":"limit-e-type","prerequisites":["limit-exp-log-standard","exp-log"],"next":["limit-at-infinity"],"related":["indeterminate-other","monotone-convergence-sequence"],"objectives":["知道 e = lim_{n→∞} (1 + 1/n)ⁿ，以及 1^∞ 為什麼是不定型。","會用 lim_{x→∞} (1 + a/x)^{bx} = e^{ab} 與 lim_{x→0} (1 + ax)^{1/x} = eᵃ。","會用「取 ln」的辦法自己推出這些結果。"],"concept":[{"heading":"① 從複利看 e","body":["本金 1、年利率 100%，一年複利 n 次，每次乘 (1 + 1/n)，一年後是 (1 + 1/n)ⁿ。n = 1 是 2，n = 10 約 2.5937，n = 100 約 2.7048，n = 1000 約 2.7169，n = 10⁶ 約 2.718280。","次數越多錢越多，但增加得越來越慢，往一個固定的數靠。這個數就是 e ≈ 2.71828。"],"tex":["e=\\lim_{n\\to\\infty}\\left(1+\\frac1n\\right)^n"]},{"heading":"② 1^∞ 是不定型","body":["底數 1 + 1/n → 1，指數 n → ∞。如果以為「1 的幾次方都是 1」，就會得到錯的答案 1。","兩股力量在拉扯：底數一直比 1 大一點點（把值往上推），但那一點點越來越小（把值往 1 拉）。誰贏、贏多少，要算才知道。"]},{"heading":"③ 通用的辦法：取 ln","body":["(1 + a/x)^{bx} = e^{bx ln(1 + a/x)}。指數的部分是 ∞ · 0 型，用〈指數與對數標準極限〉：令 t = a/x → 0，bx ln(1 + a/x) = ab · ln(1 + t)/t → ab。","eʸ 是連續函數，指數的極限是 ab，整個式子的極限就是 e^{ab}。"],"tex":["\\lim_{x\\to\\infty}\\left(1+\\frac{a}{x}\\right)^{bx}=e^{ab},\\qquad \\lim_{x\\to0}\\left(1+ax\\right)^{1/x}=e^{a}"]},{"heading":"④ 怎麼認出來","body":["底數 → 1、指數 → ∞，就是 1^∞ 型，先想 e。把底數寫成 1 + (某個 → 0 的東西)，再看指數跟那個東西相乘趨近多少。","更一般的 1^∞（例如底數是 cos x）在〈其他不定型〉處理，用的是同一招：取 ln。"]},{"heading":"為什麼 (1 + 1/n)ⁿ 一定有極限","body":["可以證明 (1 + 1/n)ⁿ 隨 n 遞增，而且永遠小於 3（二項式展開後跟 1 + 1 + 1/2 + 1/4 + … 比較）。遞增而且有上界的數列一定收斂，這是〈單調收斂定理〉。它收斂到的那個數，就定義為 e。"],"collapsible":true}],"workedExamples":[{"title":"套公式，也用 ln 檢查","prompt":"lim_{x→∞} (1 + 2/x)^{3x}","problemId":"exam-lim-012","steps":["底數 → 1、指數 → ∞，是 1^∞ 型。a = 2、b = 3。","取 ln：3x ln(1 + 2/x)。令 t = 2/x → 0，3x = 6/t，所以 3x ln(1 + 2/x) = 6 · ln(1 + t)/t → 6。","答案 e⁶。"],"answer":"e⁶"},{"title":"底數比 1 小","prompt":"lim_{x→∞} (1 − 1/x)^x","steps":["寫成 (1 + (−1)/x)^{1·x}：a = −1、b = 1。","取 ln：x ln(1 − 1/x)。令 t = −1/x → 0，x = −1/t，所以是 −ln(1 + t)/t → −1。","答案 e^{−1} = 1/e ≈ 0.368。"],"answer":"1/e"},{"title":"x → 0 的形式","prompt":"lim_{x→0} (1 + 2x)^{1/x}","steps":["x → 0 時底數 → 1、指數 1/x 的絕對值 → ∞，也是 1^∞ 型。","取 ln：ln(1 + 2x)/x = 2 · ln(1 + 2x)/(2x) → 2。","答案 e²。"],"answer":"e²"}],"pitfalls":["把 1^∞ 當成 1。","(1 + 3/x)^x 寫成 e：忘了 a = 3。","(1 + a/x)^{bx} 寫成 e^{a/b} 或 e^{a+b}：是 e^{ab}。","把 x → 0 與 x → ∞ 的形式混用：(1 + x)^x 在 x → ∞ 時不是 1^∞，它直接往 ∞ 跑。"],"checks":[{"ask":"lim_{x→∞} (1 + 1/x)^x 是？","options":[{"label":"1","why":"1^∞ 是不定型：底數雖然 → 1，但一直比 1 大一點，乘的次數又越來越多。"},{"label":"e","correct":true},{"label":"∞","why":"底數往 1 靠得夠快，值停在 2.718… 附近，不會無限變大。"}]},{"ask":"lim_{x→∞} (1 + 4/x)^{x/2} 是？","options":[{"label":"e⁸","why":"指數是 x/2，b = 1/2，ab = 4 · 1/2 = 2，不是 4 · 2。"},{"label":"e²","correct":true},{"label":"e⁴","why":"漏了指數上的 1/2。"}]},{"ask":"lim_{x→0} (1 − x)^{1/x} 是？","options":[{"label":"e⁻¹","correct":true},{"label":"e","why":"號：(1 + (−x))^{1/x}，a = −1。取 ln 是 ln(1 − x)/x → −1。"},{"label":"1","why":"1^∞ 不是 1。"}]},{"ask":"本金 10000 元、年利率 5%，一年複利 n 次。n → ∞ 時一年後的本利和是？","options":[{"label":"10500 元","why":"那是一年只複利一次。複利越頻繁錢越多，但有上限。"},{"label":"會無限變大","why":"10000(1 + 0.05/n)ⁿ → 10000e^{0.05}，是有限的。"},{"label":"10000e^{0.05} ≈ 10512.71 元","correct":true}]}],"practice":[{"id":"cx-seq-002","core":true},{"id":"cx-lim-008","core":true},{"id":"lec-05-q1d","core":true},{"id":"lec-11-q4a","core":true},{"id":"lec-11-q4b","core":true},{"id":"lx-app-004","core":true},{"id":"lec-11-q4c","challenge":true,"note":"挑戰：(n + 1)/(n − 1) = 1 + 2/(n − 1)。"},{"id":"lx-hard-005","challenge":true,"note":"挑戰：(2x + 5)/(2x − 1) = 1 + 6/(2x − 1)，再取 ln。"}]},"limit-at-infinity":{"id":"limit-at-infinity","prerequisites":["limit-laws-direct","polynomial-rational"],"next":["infinite-limits"],"related":["asymptotes"],"objectives":["說得出 lim_{x→∞} f(x) = L 的意思，以及它跟水平漸近線 y = L 的關係。","有理函數會同除以分母的最高次，並依分子分母的次數判斷答案是 0、首項係數比，還是無窮。","x → −∞ 遇到根號時，記得 √(x²) = |x| = −x。"],"concept":[{"heading":"① 意思：x 一直變大時，f(x) 往哪裡去","body":["lim_{x→∞} f(x) = L：只要 x 夠大，f(x) 就能要多靠近 L 就多靠近 L。這時直線 y = L 叫做水平漸近線。x → −∞ 同理，兩端的漸近線可以不一樣。","最基本的：p > 0 時 lim_{x→∞} 1/xᵖ = 0。分母越來越大，分數越來越小。"]},{"heading":"② 有理函數：同除以分母的最高次","body":["(3x² − x + 7)/(2x² + 5)：分子分母同除以 x²，得 (3 − 1/x + 7/x²)/(2 + 5/x²)。x → ∞ 時每個 1/x、1/x² 都 → 0，剩 3/2。","這就是〈多項式與有理函數〉裡「首項決定遠方」的精確版：除完之後，非首項的部分全部變成會趨近 0 的小項。"],"tex":["\\frac{3x^2-x+7}{2x^2+5}=\\frac{3-\\frac1x+\\frac{7}{x^2}}{2+\\frac{5}{x^2}}\\ \\longrightarrow\\ \\frac{3}{2}"]},{"heading":"③ 三種情況","body":["分子次數 < 分母次數：極限 0。分子次數 = 分母次數：首項係數的比。分子次數 > 分母次數：沒有有限的極限，往 +∞ 或 −∞（x → ∞ 時看首項係數比的正負），沒有水平漸近線。","這三句是同除最高次的結果，不是新規則；忘了就回去除一次。"]},{"heading":"④ x → −∞ 與根號","body":["√(x²) = |x|。x → −∞ 時 x 是負的，|x| = −x。所以 √(x² + 1) = √(x²(1 + 1/x²)) = |x|√(1 + 1/x²) = −x√(1 + 1/x²)。","漏了負號，答案的正負會整個反過來。"]},{"heading":"⑤ 漸近線可以被穿過","body":["水平漸近線只描述 x 很大時的行為，圖形在中間可以穿過它，甚至穿過無限多次：sin x / x 在 x → ∞ 時趨近 0，卻一再穿過 y = 0。"]}],"workedExamples":[{"title":"同次：係數比","prompt":"lim_{x→∞} (3x² − x + 7)/(2x² + 5)","problemId":"lim-004","steps":["分母最高次是 x²，分子分母同除以 x²。","(3 − 1/x + 7/x²)/(2 + 5/x²)。","x → ∞：1/x、7/x²、5/x² 都 → 0，得 3/2。水平漸近線 y = 3/2。"],"answer":"3/2"},{"title":"次數不同","prompt":"lim_{x→∞} (5x + 2)/(x² + 1) 與 lim_{x→∞} (x² + 1)/(x + 2)","steps":["第一個：同除以 x²，(5/x + 2/x²)/(1 + 1/x²) → 0/1 = 0。","第二個：同除以分母最高次 x，(x + 1/x)/(1 + 2/x)。分子 x + 1/x → ∞，分母 → 1，整個 → +∞。","第二個沒有水平漸近線；它其實貼著一條斜直線（〈漸近線〉）。"],"answer":"0；+∞（極限不存在）"},{"title":"x → −∞，根號要小心","prompt":"lim_{x→−∞} √(x² + 1)/(2x + 3)","steps":["x → −∞，可以只看 x < 0。√(x² + 1) = |x|√(1 + 1/x²) = −x√(1 + 1/x²)。","分子分母同除以 x（x 是負的，除完的號要照算）：分子 −x√(1 + 1/x²)/x = −√(1 + 1/x²)，分母 (2x + 3)/x = 2 + 3/x。","x → −∞：−√1/2 = −1/2。","同一個函數在 x → +∞ 時極限是 1/2。兩端各有一條水平漸近線：y = 1/2 與 y = −1/2。"],"answer":"−1/2"}],"pitfalls":["只有分子除以 x²，分母沒除。","x → −∞ 時把 √(x²) 寫成 x。","次數相同時寫成「次數的比」，應該是首項係數的比。","看到 ∞/∞ 就寫 1。","以為曲線永遠碰不到水平漸近線。"],"checks":[{"ask":"lim_{x→∞} (5x + 3)/(x − 2) 是？","options":[{"label":"∞","why":"分子分母都是一次，次數相同，答案是係數比 5/1。"},{"label":"0","why":"只有分子次數比分母低才是 0。"},{"label":"5","correct":true}]},{"ask":"lim_{x→∞} (x² + 1)/(x³ − x) 是？","options":[{"label":"0","correct":true},{"label":"1","why":"分母是三次、分子是二次，次數不同；同除以 x³ 後分子 → 0。"},{"label":"∞","why":"分母長得比分子快，分數會變小。"}]},{"ask":"lim_{x→−∞} √(4x² + 1)/x 是？","options":[{"label":"2","why":"x < 0 時 √(4x²) = 2|x| = −2x，除以 x 得 −2。"},{"label":"−2","correct":true},{"label":"−4","why":"√(4x²) = 2|x|，根號裡的 4 開出來是 2。"}]},{"ask":"y = (2x² + 1)/(x² + 3) 的水平漸近線是？","options":[{"label":"y = 1/3","why":"1/3 是 x = 0 時的函數值，跟 x 很大時的行為無關。"},{"label":"y = 2","correct":true},{"label":"y = 0","why":"分子分母同次，不會趨近 0。"}]}],"practice":[{"id":"cx-lim-003","core":true},{"id":"fd-lim-007","core":true},{"id":"fd-lim-008","core":true},{"id":"exam-lim-008","core":true},{"id":"cx-curve-004","core":true},{"id":"lec-01-q4b","core":true},{"id":"lx-app-002"},{"id":"lx-app-008"}]},"infinite-limits":{"id":"infinite-limits","prerequisites":["limit-one-sided","limit-factor"],"next":["squeeze-theorem"],"related":["polynomial-rational","asymptotes"],"objectives":["說得出 lim_{x→a} f(x) = ∞ 的意思，並知道它仍然是「極限不存在」的一種。","遇到 k/0 型（k ≠ 0），會分左右判斷是 +∞ 還是 −∞。","會找垂直漸近線，並排除約分後消失的洞。"],"concept":[{"heading":"① 意思：要多大有多大","body":["lim_{x→a} f(x) = ∞：只要 x 夠靠近 a（x ≠ a），f(x) 就能大過任何指定的數，例如大過 1000、大過 10⁶。= −∞ 是能小過任何指定的負數。","f(x) 沒有靠近任何一個數，所以極限其實不存在；寫 = ∞ 是在說「它怎麼不存在」：往正的方向無限變大。∞ 不是數，不能拿來做加減：∞ − ∞ 沒有意義。"]},{"heading":"② k/0 型：分子不是 0、分母靠近 0","body":["代入時分子靠近 k ≠ 0、分母靠近 0：分母越小，商的絕對值越大，所以會往 ±∞ 跑。正負號要看兩側分母的符號。","1/x：x → 0⁺ 時分母是很小的正數，1/x → +∞；x → 0⁻ 時是很小的負數，1/x → −∞。兩側不同，雙側寫不出一個 ±∞。1/x²：兩側分母都是正的，lim_{x→0} 1/x² = +∞。"]},{"heading":"③ 垂直漸近線","body":["只要左極限或右極限有一個是 +∞ 或 −∞，直線 x = a 就叫垂直漸近線。","候選是分母為 0 的點，但先約分：(x² − 1)/(x² − 3x + 2) = (x + 1)/(x − 2)（x ≠ 1），x = 1 約掉了，是洞不是漸近線（〈多項式與有理函數〉）。","不只有理函數：ln x 在 x → 0⁺ 時 → −∞，tan x 在 x → π/2⁻ 時 → +∞。"]},{"heading":"④ 判斷流程","body":["代入。得到 k/0（k ≠ 0）：一定是 ±∞，接著分左右看符號。得到 0/0：先化簡，化簡後再看一次。"]}],"workedExamples":[{"title":"左右符號不同","prompt":"求 lim_{x→3⁺} (x + 1)/(x − 3) 與 lim_{x→3⁻} (x + 1)/(x − 3)","steps":["代入：分子 → 4，分母 → 0，是 k/0 型。","x → 3⁺：x − 3 是很小的正數，4/(小正數) → +∞。","x → 3⁻：x − 3 是很小的負數，4/(小負數) → −∞。","雙側極限不存在，x = 3 是垂直漸近線。"],"answer":"右 +∞，左 −∞"},{"title":"兩側同號","prompt":"lim_{x→2} (x − 1)/(x − 2)²","steps":["分子 → 1，分母 → 0，是 k/0 型。","(x − 2)² 不管 x 在 2 的哪一側都是正的。","分子正、分母是很小的正數，兩側都 → +∞，所以 lim_{x→2} (x − 1)/(x − 2)² = +∞。"],"answer":"+∞"},{"title":"找漸近線，排除洞","prompt":"r(x) = (x² − 1)/(x² − 3x + 2) 的垂直漸近線","steps":["分母 (x − 1)(x − 2)，候選 x = 1、x = 2。分子 (x − 1)(x + 1)。","約掉 x − 1：r(x) = (x + 1)/(x − 2)（x ≠ 1）。","x = 1：約分後的式子在 1 是 2/(−1) = −2，有限，所以 lim_{x→1} r(x) = −2，是洞。","x = 2：分子 3、分母 0，k/0 型，是垂直漸近線。"],"answer":"只有 x = 2（x = 1 是洞）"}],"pitfalls":["分母為 0 的點全部當成垂直漸近線，沒有先約分。","只看一側的符號就寫 +∞。","把 ∞ 當數字做運算，例如 ∞ − ∞ = 0。","寫 1/0 = ∞：1/0 沒有定義，是「x → 0 時 1/x 的行為」才談得上 ±∞。"],"checks":[{"ask":"lim_{x→0} 1/x² 是？","options":[{"label":"+∞（兩側都往正無窮）","correct":true},{"label":"左 −∞、右 +∞","why":"那是 1/x。x² 在 0 的兩側都是正的。"},{"label":"0","why":"是分母 x² 往 0 靠；整個分式往無窮大跑。"}]},{"ask":"lim_{x→1⁻} 2/(x − 1) 是？","options":[{"label":"+∞","why":"x < 1 時 x − 1 是很小的負數，2 除以小負數是很大的負數。"},{"label":"−∞","correct":true},{"label":"2","why":"分母往 0 靠，分式不會停在 2。"}]},{"ask":"f(x) = (x − 3)/(x² − 9) 的垂直漸近線是？","options":[{"label":"x = 3 與 x = −3","why":"x = 3 約得掉：約分後 1/(x + 3) 在 3 是 1/6，那裡是洞。"},{"label":"沒有","why":"x = −3 約不掉：分子 → −6、分母 → 0，是 k/0 型。"},{"label":"只有 x = −3","correct":true}]},{"ask":"lim_{x→0⁺} ln x 是？","options":[{"label":"0","why":"ln 1 = 0，不是 ln 0。x 越靠近 0，ln x 越負。"},{"label":"−∞","correct":true},{"label":"+∞","why":"0 < x < 1 時 ln x 是負的。"}]}],"practice":[{"id":"cx-curve-006","core":true},{"id":"lec-04-q3a"},{"id":"si-set-003","note":"題目問不連續點；再多想一步：哪一個是洞、哪一個是漸近線？"},{"id":"sk-014"}]},"squeeze-theorem":{"id":"squeeze-theorem","prerequisites":["limit-laws-direct","limit-existence","trig-functions"],"next":["continuity-definition"],"related":["epsilon-delta-definition","limit-trig-standard"],"objectives":["說得出夾擠定理的條件與結論。","遇到「有界的東西 × 趨近 0 的東西」，會寫出上下界把它夾到 0。","會用 x − 1 < ⌊x⌋ ≤ x、−1 ≤ sin ≤ 1 這類不等式，處理 x → ∞ 與取整函數。"],"concept":[{"heading":"① 敘述","body":["在 a 附近（a 本身可以除外）有 g(x) ≤ f(x) ≤ h(x)，而且 lim_{x→a} g(x) = lim_{x→a} h(x) = L。那麼 lim_{x→a} f(x) = L。","直覺：f 被夾在兩條往同一點擠的曲線中間，沒有別的地方可去。結論不只說極限是 L，也保證了極限存在。"],"tex":["g(x)\\le f(x)\\le h(x),\\quad \\lim_{x\\to a}g=\\lim_{x\\to a}h=L\\ \\Longrightarrow\\ \\lim_{x\\to a}f=L"]},{"heading":"② 為什麼需要它","body":["lim_{x→0} x² sin(1/x)：sin(1/x) 在 0 沒有極限（振盪），所以不能用乘積定律拆成 lim x² · lim sin(1/x)。","但 sin(1/x) 雖然亂跳，大小一定在 −1 與 1 之間。乘上 x²（≥ 0）：−x² ≤ x² sin(1/x) ≤ x²。兩邊都 → 0，中間只好也 → 0。"]},{"heading":"③ 最常見的樣子：有界 × 趨近 0","body":["|f(x)| ≤ |g(x)| 而且 g(x) → 0，就有 f(x) → 0。因為 −|g(x)| ≤ f(x) ≤ |g(x)|，兩側都 → 0。用絕對值寫比較不會搞錯不等式的方向（x 可能是負的）。","這招只直接給出「→ 0」。極限是 L ≠ 0 時，改成夾 |f(x) − L|。"]},{"heading":"④ x → ∞ 也能用","body":["sin x / x：x > 0 時 −1/x ≤ sin x / x ≤ 1/x，兩邊 → 0，所以 lim_{x→∞} sin x / x = 0。","取整函數：x − 1 < ⌊x⌋ ≤ x 對所有 x 成立，這是夾擠⌊x⌋最好用的不等式。"]},{"heading":"證明（用 ε-δ）","body":["給任意 ε > 0。因為 g → L，存在 δ₁ 使 0 < |x − a| < δ₁ 時 L − ε < g(x)；因為 h → L，存在 δ₂ 使 0 < |x − a| < δ₂ 時 h(x) < L + ε；設不等式 g ≤ f ≤ h 在 0 < |x − a| < δ₃ 成立。","取 δ = min(δ₁, δ₂, δ₃)。當 0 < |x − a| < δ：L − ε < g(x) ≤ f(x) ≤ h(x) < L + ε，也就是 |f(x) − L| < ε。這正是 lim_{x→a} f(x) = L 的定義（〈ε-δ 定義〉）。"],"collapsible":true}],"workedExamples":[{"title":"有界乘以趨近 0","prompt":"lim_{x→0} x² cos(5/x)","problemId":"lx-sq-001","steps":["cos(5/x) 在 0 附近振盪，沒有極限，不能拆開。","但 |cos(5/x)| ≤ 1，所以 |x² cos(5/x)| ≤ x²，也就是 −x² ≤ x² cos(5/x) ≤ x²。","lim_{x→0} (−x²) = 0，lim_{x→0} x² = 0。","由夾擠定理，極限是 0。"],"answer":"0"},{"title":"x → ∞，極限不是 0","prompt":"lim_{x→∞} (2x + 3 sin x)/(x + 5)","problemId":"lx-sq-002","steps":["−1 ≤ sin x ≤ 1，所以 2x − 3 ≤ 2x + 3 sin x ≤ 2x + 3。","x > 0 時 x + 5 > 0，除過去不等號不變：(2x − 3)/(x + 5) ≤ 原式 ≤ (2x + 3)/(x + 5)。","兩邊都是同次有理函數，x → ∞ 時都 → 2/1 = 2。","由夾擠定理，極限是 2。"],"answer":"2"},{"title":"取整函數","prompt":"lim_{x→∞} ⌊x⌋/x","problemId":"lm-fl-004","steps":["x − 1 < ⌊x⌋ ≤ x。","x > 0 時同除以 x：(x − 1)/x < ⌊x⌋/x ≤ 1。","(x − 1)/x = 1 − 1/x → 1，右邊是常數 1。","由夾擠定理，極限是 1。"],"answer":"1"}],"pitfalls":["寫 lim x² sin(1/x) = lim x² · lim sin(1/x)：後者不存在，不能拆。","上下界的極限不相等，還是套用定理。","乘上一個可能是負數的量時，忘了不等號會反向；用絕對值寫最安全。","以為夾擠只能證明極限是 0。"],"checks":[{"ask":"在 0 附近 −x² ≤ f(x) ≤ x²。lim_{x→0} f(x) 是？","options":[{"label":"0","correct":true},{"label":"不一定存在","why":"夾擠定理正好保證它存在：兩側都 → 0。"},{"label":"無法判斷，要知道 f 的式子","why":"不需要；被夾住就夠了。"}]},{"ask":"lim_{x→0} x sin(1/x) 是？","options":[{"label":"1","why":"那是 lim_{u→0} sin u / u 的樣子；這裡 1/x → ∞，不是 → 0。"},{"label":"不存在","why":"sin(1/x) 雖然振盪，但 |x sin(1/x)| ≤ |x| → 0，被壓到 0。"},{"label":"0","correct":true}]},{"ask":"在 0 附近 1 ≤ f(x) ≤ 1 + x²。lim_{x→0} f(x) 是？","options":[{"label":"0","why":"下界是常數 1，f 至少是 1，不會靠近 0。"},{"label":"1","correct":true},{"label":"不一定存在","why":"上下界都 → 1，夾擠定理保證極限存在。"}]},{"ask":"lim_{x→∞} cos x / x 是？","options":[{"label":"0","correct":true},{"label":"1","why":"cos x 在 −1 與 1 之間，除以越來越大的 x，會被壓到 0。"},{"label":"不存在","why":"cos x 振盪，但 |cos x / x| ≤ 1/x → 0。"}]}],"practice":[{"id":"cx-lim-010","core":true},{"id":"lm-sq-002","core":true},{"id":"lec-01-q2b","core":true},{"id":"lx-sq-005","core":true},{"id":"lm-fl-007","core":true},{"id":"lec-01-q2a"},{"id":"px-sq-001"},{"id":"lm-sq-005","challenge":true,"note":"挑戰：先確認 (1 − cos x)/x → 0（〈三角標準極限〉），再夾。"},{"id":"lec-01-q2c","challenge":true,"note":"挑戰：令 t = 1/x，用 t − 1 < ⌊t⌋ ≤ t，x 的正負要分開處理。"}]},"continuity-definition":{"id":"continuity-definition","prerequisites":["limit-existence","limit-laws-direct"],"next":["discontinuity-types"],"related":["continuity-formal","limit-factor","limit-trig-standard"],"objectives":["說得出 f 在 a 連續的三個條件，並逐條檢查。","知道哪些函數在哪裡連續，以及「可以直接代入」就是連續。","會解分段函數的連續參數題，會補一個值讓函數連續。"],"concept":[{"heading":"① 定義：極限等於函數值","body":["f 在 x = a 連續，意思是 lim_{x→a} f(x) = f(a)。這一行其實包含三件事：f(a) 有定義；lim_{x→a} f(x) 存在；兩者相等。少一件就不連續。","直覺的說法是「畫到 x = a 不用抬筆」。這是直覺，不是定義：它對奇怪的函數不可靠，而且只描述了圖形，檢查時一律回到上面三條。"],"tex":["\\lim_{x\\to a}f(x)=f(a)"]},{"heading":"② 哪些函數連續","body":["多項式處處連續；有理函數在分母不為 0 的每一點連續；√x、eˣ、ln x、sin x、cos x 在它們的定義域上連續。","連續函數相加、相減、相乘、相除（分母不為 0）、合成，結果還是連續。所以〈直接代入與極限定律〉裡「可以直接代入」的函數，正是在那一點連續的函數。"]},{"heading":"③ 合成：極限可以穿進連續函數裡","body":["若 lim_{x→a} g(x) = b，而 f 在 b 連續，則 lim_{x→a} f(g(x)) = f(b)。例：lim_{x→1} √((x² − 1)/(x − 1))，裡面的極限是 2，√ 在 2 連續，答案 √2。"]},{"heading":"④ 區間上的連續","body":["在開區間 (a, b) 連續：裡面每一點都連續。在閉區間 [a, b] 連續：裡面每點連續，而且端點只看一側：lim_{x→a⁺} f(x) = f(a)，lim_{x→b⁻} f(x) = f(b)。例：√x 在 [0, ∞) 連續，0 那一點用右極限。"]},{"heading":"⑤ 嚴格版預告","body":["用 ε-δ 寫出來是：任給 ε > 0，存在 δ > 0，使 |x − a| < δ 時 |f(x) − f(a)| < ε。跟極限的定義只差兩處：x = a 本身也算進來，而且 L 換成 f(a)。細節在〈連續的正式定義〉。"],"collapsible":true}],"workedExamples":[{"title":"補一個值","prompt":"f(x) = (x² − 9)/(x − 3)（x ≠ 3），f(3) = k。k 是多少時 f 在 3 連續？","problemId":"cx-cont-001","steps":["連續要 lim_{x→3} f(x) = f(3) = k。","x ≠ 3 時 (x² − 9)/(x − 3) = x + 3（〈0/0：因式分解〉），極限是 6。","所以 k = 6。"],"answer":"k = 6"},{"title":"分段函數的參數","prompt":"f(x) = ax + 1（x ≤ 2），x²（x > 2）。a 是多少時 f 在 2 連續？","problemId":"cx-cont-002","steps":["f(2)：2 屬於 x ≤ 2 那段，f(2) = 2a + 1。左極限也是 2a + 1（同一段，多項式）。","右極限：x² → 4。","三條件要成立：2a + 1 = 4，a = 3/2。"],"answer":"a = 3/2"},{"title":"極限穿進根號","prompt":"lim_{x→1} √((x² − 1)/(x − 1))","steps":["裡面：(x² − 1)/(x − 1) = x + 1（x ≠ 1），x → 1 時 → 2。","√ 在 2 連續，所以極限可以穿進去：√2。"],"answer":"√2"}],"pitfalls":["只檢查極限存在，沒檢查 f(a) 有定義、兩者相等。","只檢查 f(a) 有定義，就說連續。","分段題把分界點代進不包含它的那一段。","把 1/x 說成「在定義域上不連續」：它在定義域的每一點都連續，x = 0 根本不在定義域裡。"],"checks":[{"ask":"f(2) = 5，而且 lim_{x→2} f(x) = 5。f 在 2：","options":[{"label":"不連續","why":"三個條件都滿足：有定義、極限存在、兩者相等。"},{"label":"連續","correct":true},{"label":"要看圖才知道","why":"定義只要這三件事，題目都給了。"}]},{"ask":"f(x) = (x² − 4)/(x − 2) 在 x = 2：","options":[{"label":"連續，因為極限是 4","why":"極限存在只是三個條件之一；f(2) 沒有定義。"},{"label":"不連續，因為極限不存在","why":"極限存在，是 4。缺的是 f(2)。"},{"label":"不連續，因為 f(2) 沒有定義","correct":true}]},{"ask":"f(x) = x² + b（x < 1），3x − 1（x ≥ 1）在 1 連續。b 是？","options":[{"label":"1","correct":true},{"label":"2","why":"左段在 1 的極限是 1 + b，不是 b；要 1 + b = 2。"},{"label":"0","why":"左極限 1 + b 要等於 f(1) = 3 − 1 = 2，b = 1。"}]},{"ask":"哪一個函數在所有實數上連續？","options":[{"label":"1/(x² − 1)","why":"x = ±1 時分母是 0，那兩點沒有定義。"},{"label":"x²/(x² + 1)","correct":true},{"label":"√x","why":"x < 0 沒有定義。"}]}],"practice":[{"id":"lx-con-001","core":true},{"id":"lx-con-002","core":true,"note":"極限要用〈三角標準極限〉。"},{"id":"lec-01-q4a","core":true},{"id":"si-set-021"},{"id":"cx-cont-005"},{"id":"lec-01-m4"},{"id":"lec-01-q3a","challenge":true,"note":"挑戰：兩個分界點、兩個參數，各列一條方程式。"}]},"discontinuity-types":{"id":"discontinuity-types","prerequisites":["continuity-definition","infinite-limits","squeeze-theorem"],"next":["intermediate-value-theorem"],"related":["limit-one-sided"],"objectives":["認得四種不連續：可去、跳躍、無窮、振盪。","會用左右極限依序判斷是哪一種。","知道只有可去不連續能靠「重新定義一個點」修好。"],"concept":[{"heading":"① 可去不連續","body":["lim_{x→a} f(x) 存在，但 f(a) 沒有定義，或 f(a) 不等於極限。圖形上是一個洞。","只要把 f(a) 重新定義成那個極限值，就連續了，所以叫「可去」。"]},{"heading":"② 跳躍不連續","body":["左極限、右極限都存在，但不相等。圖形上是兩段錯開。","改一個點的值修不好：不管 f(a) 是多少，左右都接不起來。"]},{"heading":"③ 無窮不連續","body":["至少一側的極限是 +∞ 或 −∞，也就是有垂直漸近線（〈無窮極限與垂直漸近線〉）。例：1/(x − 1)² 在 x = 1。"]},{"heading":"④ 振盪不連續","body":["函數在 a 附近不停擺盪，不往任何數靠、也不往 ±∞ 跑。例：sin(1/x) 在 0。","對照：x sin(1/x)（x ≠ 0）、f(0) = 0 是連續的。它也在振盪，但振幅被 |x| 壓到 0（〈夾擠定理〉），所以極限是 0 = f(0)。"]},{"heading":"⑤ 判斷順序","body":["先分別算左、右極限。都是有限數而且相等：可去（若 f(a) 不等於它或沒定義）。都是有限數但不相等：跳躍。有一側是 ±∞：無窮。有一側既不是有限數、也不是 ±∞：通常就是振盪。","一個用詞提醒：x = 0 不在 1/x 的定義域，嚴格說「連續」只在定義域的點上討論；課本通常仍把 x = 0 叫做 1/x 的無窮不連續點，意思是那裡有垂直漸近線。"]}],"workedExamples":[{"title":"一個函數裡兩種","prompt":"f(x) = (x² − x − 2)/(x² − 4)。分類每一個不連續點。","steps":["分母 (x − 2)(x + 2)，在 x = ±2 沒有定義，兩點都不連續。分子 (x − 2)(x + 1)。","x = 2：約掉 x − 2，x ≠ 2 時 f(x) = (x + 1)/(x + 2)，極限 3/4 存在。可去不連續；補 f(2) = 3/4 就連續。","x = −2：約分後分子 → −1、分母 → 0，是 k/0 型，兩側往 ±∞。無窮不連續。"],"answer":"x = 2 可去（極限 3/4），x = −2 無窮"},{"title":"絕對值造成跳躍","prompt":"f(x) = |x − 4|/(x − 4) 在 x = 4 是哪一種不連續？","problemId":"lx-con-005","steps":["x > 4：|x − 4| = x − 4，f = 1，右極限 1。","x < 4：|x − 4| = −(x − 4)，f = −1，左極限 −1。","左右都是有限數，但不相等：跳躍不連續。"],"answer":"跳躍不連續"},{"title":"振盪 vs. 被壓住的振盪","prompt":"sin(1/x) 在 0 是哪一種？x sin(1/x)（x ≠ 0）、f(0) = 0 在 0 連續嗎？","steps":["sin(1/x)：x = 1/(6π) 時是 sin(6π) = 0，x = 2/(13π) 時是 sin(13π/2) = 1，而這種 x 要多靠近 0 都找得到。不往任何數靠，也不爆掉：振盪不連續。","x sin(1/x)：|x sin(1/x)| ≤ |x| → 0，夾擠得極限 0。","極限 0 等於 f(0) = 0，所以連續。"],"answer":"sin(1/x)：振盪不連續；x sin(1/x) 補 f(0) = 0 後連續"}],"pitfalls":["看到分母為 0 就說是無窮不連續，沒先約分：可能是可去。","把跳躍當成可去，以為改一個點的值就能修好。","把振盪當成無窮：sin(1/x) 一直在 −1 與 1 之間，沒有爆掉。","只看圖形「有沒有斷」，沒用左右極限判斷。"],"checks":[{"ask":"(x² − 1)/(x − 1) 在 x = 1 是哪一種不連續？","options":[{"label":"無窮","why":"分子在 1 也是 0；約掉後 x + 1 在 1 是 2，不會爆掉。"},{"label":"可去","correct":true},{"label":"跳躍","why":"左右都往 2 靠，不是兩個不同的數。"}]},{"ask":"⌊x⌋ 在 x = 2 是哪一種不連續？","options":[{"label":"跳躍","correct":true},{"label":"可去","why":"左極限 1、右極限 2，不相等；改 f(2) 的值修不好。"},{"label":"無窮","why":"⌊x⌋ 在 2 附近只有 1 和 2 兩個值，沒有爆掉。"}]},{"ask":"1/(x − 1)² 在 x = 1 是哪一種不連續？","options":[{"label":"可去","why":"分子是 1，約不掉；分母 → 0，值往 +∞ 跑。"},{"label":"振盪","why":"它沒有來回擺，而是一路往 +∞。"},{"label":"無窮","correct":true}]},{"ask":"哪一種不連續，只要重新定義一個點的值就能變連續？","options":[{"label":"跳躍","why":"左右極限不同，一個點的值無法同時接上兩邊。"},{"label":"可去","correct":true},{"label":"無窮","why":"極限根本不是有限數，沒有值可以補。"}]}],"practice":[{"id":"lx-con-003","core":true},{"id":"si-set-003","core":true,"note":"找到兩個不連續點後，再判斷各是哪一種。"},{"id":"lm-sq-006","core":true},{"id":"lm-os-005","core":true},{"id":"si-set-020"},{"id":"si-set-022"},{"id":"lec-01-m4"}]},"intermediate-value-theorem":{"id":"intermediate-value-theorem","prerequisites":["continuity-definition"],"next":["average-rate"],"related":["ivt-proof","completeness-axiom"],"objectives":["說得出中間值定理的條件與結論，知道它只保證「存在」。","會用它證明方程式有根：構造函數、確認連續、找兩個異號的端點。","會用二分法把根的位置一步一步縮小。"],"concept":[{"heading":"① 敘述","body":["f 在 [a, b] 上連續，N 是介於 f(a) 與 f(b) 之間的任何一個數，那麼 (a, b) 裡至少有一個 c 使 f(c) = N。","最常用的特例：f(a) 與 f(b) 一正一負，就至少有一個 c ∈ (a, b) 使 f(c) = 0。"],"tex":["f\\ \\text{在}\\ [a,b]\\ \\text{連續},\\ f(a)<0<f(b)\\ \\Longrightarrow\\ \\exists\\,c\\in(a,b),\\ f(c)=0"]},{"heading":"② 直覺：不抬筆就得穿過去","body":["從 x 軸下方的一點畫到上方的一點，中間不抬筆，一定會碰到 x 軸。這是直覺，不是證明：「不抬筆」只是圖像，而定理之所以成立，靠的是實數沒有縫隙。"]},{"heading":"為什麼要用到「實數沒有縫隙」","body":["如果只有有理數，定理會失敗：f(x) = x² − 2 在 [1, 2] 上連續，f(1) = −1 < 0 < 2 = f(2)，但沒有任何有理數 c 讓 c² = 2。","實數把 √2 這種縫隙補起來了。把「沒有縫隙」寫成公理是〈完備性公理〉，用它證明本定理在〈中間值定理的證明〉。"],"collapsible":true},{"heading":"③ 條件不能少","body":["連續是必要的：f(x) = 1/x，f(−1) = −1、f(1) = 1，但 1/x 永遠不是 0。問題在 x = 0：1/x 在那裡沒有定義，在 [−1, 1] 上不連續，定理不能用。"]},{"heading":"④ 它不說的事","body":["不說根在哪裡，也不說有幾個：「至少一個」，可能更多。","反過來不成立：沒有變號不代表沒有根。x² 在 [−1, 1] 的兩端都是 1，卻有根 x = 0。"]},{"heading":"⑤ 二分法：把存在變成近似值","body":["知道 [a, b] 裡有根之後，算中點 m 的函數值，留下兩端仍然異號的那一半。每做一次區間長度減半，做 10 次就縮成原來的 1/1024。"]}],"workedExamples":[{"title":"證明方程式有根","prompt":"證明 x³ − x − 1 = 0 在 (1, 2) 之間有解。","steps":["令 f(x) = x³ − x − 1。它是多項式，在 [1, 2] 上連續，定理的條件成立。","f(1) = 1 − 1 − 1 = −1 < 0，f(2) = 8 − 2 − 1 = 5 > 0。","0 介於 −1 與 5 之間，由中間值定理，存在 c ∈ (1, 2) 使 f(c) = 0。","定理沒說 c 是多少（其實約 1.3247），但「有解」已經證完了。"],"answer":"得證：(1, 2) 內至少有一個根"},{"title":"把方程式改寫成「某函數 = 0」","prompt":"證明 cos x = x 在 (0, π/2) 內至少有一個解。","problemId":"lec-01-q3b","steps":["移項：令 g(x) = cos x − x。cos x 與 x 都連續，相減也連續。","g(0) = cos 0 − 0 = 1 > 0。","g(π/2) = cos(π/2) − π/2 = −π/2 < 0。","由中間值定理，存在 c ∈ (0, π/2) 使 g(c) = 0，也就是 cos c = c。"],"answer":"得證"},{"title":"二分法","prompt":"x³ + x − 1 = 0 在 (0, 1) 有根。用二分法把根框在長度 1/8 的區間裡。","steps":["f(x) = x³ + x − 1：f(0) = −1 < 0，f(1) = 1 > 0。","中點 0.5：f(0.5) = 0.125 + 0.5 − 1 = −0.375 < 0。變號在 [0.5, 1]。","中點 0.75：f(0.75) = 0.421875 + 0.75 − 1 = 0.171875 > 0。變號在 [0.5, 0.75]。","中點 0.625：f(0.625) = 0.244140625 + 0.625 − 1 = −0.130859375 < 0。變號在 [0.625, 0.75]，長度 1/8。"],"answer":"根在 [0.625, 0.75] 裡（實際約 0.6823）"}],"pitfalls":["沒檢查連續就套定理。","以為定理保證「恰好一個」根。","以為端點沒有變號，就一定沒有根。","以為定理說了根在中點，或說了根是多少。"],"checks":[{"ask":"f 處處連續，f(0) = −3、f(1) = 2。可以確定什麼？","options":[{"label":"0 和 1 之間恰好有一個 x 使 f(x) = 0","why":"定理只保證至少一個；圖形可以上下穿過 x 軸好幾次。"},{"label":"0 和 1 之間至少有一個 x 使 f(x) = 0","correct":true},{"label":"f(0.5) = 0","why":"定理只說存在，沒說在哪裡。"}]},{"ask":"f(x) = 1/x，f(−1) = −1、f(1) = 1。所以？","options":[{"label":"−1 和 1 之間一定有根","why":"1/x 在 x = 0 沒有定義，在 [−1, 1] 上不連續，定理不能用；事實上 1/x 永遠不是 0。"},{"label":"根是 x = 0","why":"1/0 沒有意義，0 不在定義域裡。"},{"label":"定理不能用，而且 1/x 沒有根","correct":true}]},{"ask":"f 在 [1, 3] 上連續，f(1) = 2、f(3) = 8。下面哪一句一定對？","options":[{"label":"存在 c ∈ (1, 3) 使 f(c) = 5","correct":true},{"label":"f(2) = 5","why":"定理只保證某個 c 讓 f(c) = 5，不保證 c 是中點。"},{"label":"不一定有 c 使 f(c) = 5","why":"5 介於 2 與 8 之間，f 又連續，定理保證存在。"}]},{"ask":"f(x) = x² 在 [−1, 1]：f(−1) = f(1) = 1，沒有變號。所以？","options":[{"label":"一定沒有根","why":"定理只是單向的。x² 在 x = 0 就是 0。"},{"label":"一定有兩個根","why":"定理在這裡什麼都沒說；x² 在 [−1, 1] 只有一個根 0。"},{"label":"定理不保證有根；但 x² 其實有根 0","correct":true}]}],"practice":[{"id":"lec-01-m5","core":true},{"id":"px-ivt-001","core":true},{"id":"px-ivt-002","core":true,"note":"先找兩個代起來異號的點，例如 x = 0 與 x = 1。"},{"id":"cx-cont-004","challenge":true,"note":"挑戰：中間值定理給「至少一個」；要說「恰好一個」，還要說明 f 遞增。"}]}});
